import type { PoolClient } from "pg";

export class WorkspaceMaintenanceFencedError extends Error {
  constructor() {
    super("WORKSPACE_MAINTENANCE_FENCED");
  }
}

/** Pins trusted maintenance to the current generation without bypassing a source fence. */
export async function setCurrentWorkspaceRoutingEpoch(
  client: PoolClient,
  workspaceId: string,
): Promise<number> {
  await client.query(
    `INSERT INTO regional_workspace_migration_fences
       (workspace_id, source_epoch, active_epoch)
     VALUES ($1, 0, 1)
     ON CONFLICT (workspace_id) DO NOTHING`,
    [workspaceId],
  );
  const fence = await client.query<{ source_epoch: string; active_epoch: string }>(
    `SELECT source_epoch::text, active_epoch::text
       FROM regional_workspace_migration_fences
      WHERE workspace_id = $1
      FOR SHARE`,
    [workspaceId],
  );
  const row = fence.rows[0];
  if (row && Number(row.source_epoch) > 0) {
    throw new WorkspaceMaintenanceFencedError();
  }
  const epoch = Number(row?.active_epoch);
  if (!Number.isSafeInteger(epoch) || epoch < 1) {
    throw new Error("WORKSPACE_MAINTENANCE_EPOCH_INVALID");
  }
  await client.query(
    "SELECT set_config('skillplane.workspace_routing_epoch', $1, true)",
    [String(epoch)],
  );
  return epoch;
}
import { createAuthfnSchema, createDatabaseClient } from "@skillplane/db";
import type { AuthFnRuntimeConfig } from "authfn";
import { issueSession } from "authfn/core/sessions";
import { createUser } from "authfn/core/users";
import { Pool } from "pg";

export interface TenantFixture {
  readonly workspaceId: string;
  readonly userId: string;
  readonly sessionToken: string;
  readonly csrfToken: string;
  readonly skillId: string;
  readonly contextId: string;
}

export async function seedTenantFixture(
  databaseUrl: string,
  suffix: string,
  options: { role?: "viewer" | "editor" | "admin" | "owner" } = {},
): Promise<TenantFixture> {
  const database = createDatabaseClient({
    connectionString: databaseUrl,
    applicationName: `skillplane-fixture-${suffix}`,
    maxConnections: 2,
  });
  try {
    const now = new Date();
    const userId = `user:${suffix}`;
    const workspaceId = `workspace:${suffix}`;
    const skillId = `skill:${suffix}`;
    const contextId = `context:${suffix}`;
    const authConfig: AuthFnRuntimeConfig = {
      database: database.adapter,
      plugins: [],
      namespace: "authfn",
    };
    createAuthfnSchema({ database: database.adapter });
    await createUser(authConfig, {
      id: userId,
      primaryEmail: `${suffix}@example.test`,
      emailVerifiedAt: now,
      metadata: { fixture: true },
    });
    const issued = await issueSession(
      authConfig,
      {},
      {
        userId,
        primaryEmail: `${suffix}@example.test`,
        methods: ["email-otp"],
      },
    );
    await database.pool.query(
      `INSERT INTO workspaces (id, workspace_id, slug, name)
       VALUES ($1, $1, $2, $3)`,
      [workspaceId, `workspace-${suffix}`, `Workspace ${suffix}`],
    );
    await database.pool.query(
      `INSERT INTO workspace_memberships
         (id, workspace_id, user_id, role)
       VALUES ($1, $2, $3, $4)`,
      [`membership:${suffix}`, workspaceId, userId, options.role ?? "owner"],
    );
    await database.pool.query(
      `INSERT INTO skills
         (id, workspace_id, slug, name, description, tags, created_by_user_id)
       VALUES ($1, $2, $3, $4, $5, $6, $7)`,
      [
        skillId,
        workspaceId,
        `pr-review-${suffix}`,
        `PR Review ${suffix}`,
        `Tenant ${suffix} private review guidance`,
        ["review", suffix],
        userId,
      ],
