import { readFile } from "node:fs/promises";
import { basename, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

interface LocalRuntimeFile {
  readonly databaseUrl?: unknown;
  readonly testDatabaseUrl?: unknown;
}

const moduleParent = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const packageRoot =
  basename(moduleParent) === "dist" ? resolve(moduleParent, "..") : moduleParent;
export const projectRoot = resolve(packageRoot, "..", "..");

function requirePostgresUrl(value: unknown, source: string): string {
  if (typeof value !== "string") {
    throw new Error(`${source} does not contain a Postgres connection string`);
  }
  const parsed = new URL(value);
  if (
    !["postgres:", "postgresql:"].includes(parsed.protocol) ||
    !parsed.hostname ||
    !parsed.username ||
    !parsed.pathname.slice(1)
  ) {
    throw new Error(`${source} is not a valid Postgres connection string`);
  }
  return value;
}

async function readLocalRuntime(): Promise<LocalRuntimeFile> {
  const path = resolve(projectRoot, ".data", "local-runtime.json");
  return JSON.parse(await readFile(path, "utf8")) as LocalRuntimeFile;
}

export async function resolveMigrationDatabaseUrl(): Promise<string> {
  const configured = process.env.MIGRATION_DATABASE_URL ?? process.env.DATABASE_URL;
  if (configured) {
    return requirePostgresUrl(configured, "database environment");
  }
  const runtime = await readLocalRuntime();
  return requirePostgresUrl(runtime.databaseUrl, ".data/local-runtime.json");
}

export async function resolveTestDatabaseUrl(): Promise<string> {
  if (process.env.TEST_DATABASE_URL) {
    return requirePostgresUrl(process.env.TEST_DATABASE_URL, "TEST_DATABASE_URL");
  }
  const runtime = await readLocalRuntime();
  if (runtime.testDatabaseUrl) {
    return requirePostgresUrl(runtime.testDatabaseUrl, ".data/local-runtime.json");
  }
  const source = new URL(
    requirePostgresUrl(runtime.databaseUrl, ".data/local-runtime.json"),
  );
  source.pathname = "/skillplane_test";
  return source.toString();
}

export function assertDisposableDatabaseUrl(databaseUrl: string): void {
  const parsed = new URL(databaseUrl);
  const databaseName = parsed.pathname.slice(1);
  const localHost = ["127.0.0.1", "localhost", "::1"].includes(parsed.hostname);
  if (!localHost || !databaseName.endsWith("_test")) {
    throw new Error(
      `Refusing destructive reset for non-local/non-test database "${parsed.hostname}/${databaseName}"`,
    );
  }
}
import { migrateDatabase, resolveTestDatabaseUrl } from "@skillplane/db";
import {
  purgeTenantFixture,
  seedTenantFixture,
  type TenantFixture,
} from "@skillplane/testing";
import {
  rollupUtcDay,
  runAuditRetention,
  writeAuditEvent,
} from "@skillplane/observability";
import { Pool } from "pg";
import { afterAll, beforeAll, describe, expect, it } from "vitest";

let databaseUrl: string;
let pool: Pool;
let tenant: TenantFixture;
const suffix = `audit-analytics-${crypto.randomUUID().replaceAll("-", "").slice(0, 12)}`;

function daysAgo(days: number, hour = 12): Date {
  const value = new Date(Date.now() - days * 86_400_000);
  value.setUTCHours(hour, 0, 0, 0);
  return value;
}

function day(value: Date): string {
  return value.toISOString().slice(0, 10);
}

beforeAll(async () => {
  databaseUrl = await resolveTestDatabaseUrl();
  await migrateDatabase(databaseUrl);
  tenant = await seedTenantFixture(databaseUrl, suffix);
  pool = new Pool({
    connectionString: databaseUrl,
    application_name: `audit-analytics-${suffix}`,
    max: 4,
  });
});

afterAll(async () => {
  await pool.end();
  await purgeTenantFixture(databaseUrl, suffix);
});

describe("audit retention and analytics rollups", () => {
  it("rebuilds a UTC day idempotently and retains aggregates after detail expiry", async () => {
    const retrievalAt = daysAgo(91);
    const mutationAt = daysAgo(400);
    for (let index = 0; index < 10; index += 1) {
      await writeAuditEvent(pool, {
        workspaceId: tenant.workspaceId,
        eventType: "mcp.skill_retrieve.success",
        action: "skill_retrieve",
        outcome: "success",
        actorType: "service_principal",
        actorId: "service:analytics-agent",
        requestId: `request:retrieval:${suffix}:${String(index)}`,
        resourceType: "skill_version",
        resourceId: `skill-version:${suffix}`,
        skillId: tenant.skillId,
        versionId: `skill-version:${suffix}`,
        contextId: tenant.contextId,
        agent: "Codex",
        model: "gpt-5",
        caller: {
          agentId: "agent:codex",
          agentName: "Codex",
          modelProvider: "openai",
          modelName: "gpt-5",
          modelVersion: "2026-07",
          clientName: "zed",
          clientVersion: "1.0",
          runId: `run:${String(index)}`,
          sessionId: "session:analytics",
          conversationId: "conversation:analytics",
        },
        latencyMs: 10 + index,
        channel: "mcp",
        retentionClass: "detailed_read_90d",
        occurredAt: retrievalAt,
      });
    }
    for (let index = 0; index < 2; index += 1) {
      await writeAuditEvent(pool, {
        workspaceId: tenant.workspaceId,
        eventType: "skill.amendment.created",
        action: "skills:amend",
        outcome: "success",
        actorType: "service_principal",
        actorId: "service:analytics-agent",
        requestId: `request:amendment:${suffix}:${String(index)}`,
        resourceType: "skill_version",
        resourceId: `candidate:${index}`,
        skillId: tenant.skillId,
        versionId: `candidate:${index}`,
        channel: "mcp",
        retentionClass: "permanent",
        occurredAt: mutationAt,
      });
    }
    await writeAuditEvent(pool, {
      workspaceId: tenant.workspaceId,
      eventType: "oauth.refresh.reuse_detected",
      action: "oauth:refresh",
      outcome: "denied",
      actorType: "user",
      actorId: tenant.userId,
      userId: tenant.userId,
      requestId: `request:reuse:${suffix}`,
      resourceType: "oauth_client",
      resourceId: "client:analytics",
      channel: "oauth",
      retentionClass: "permanent",
      occurredAt: mutationAt,
    });

    const first = await rollupUtcDay(pool, {
      day: day(retrievalAt),
      workspaceId: tenant.workspaceId,
    });
    const second = await rollupUtcDay(pool, {
      day: day(retrievalAt),
      workspaceId: tenant.workspaceId,
    });
    expect(first.sourceEvents).toBe(10);
    expect(second.sourceEvents).toBe(10);

    const before = await pool.query<{
      retrieval_count: string;
      unique_principal_count: string;
      unique_agent_count: string;
      latency_p50_ms: number;
      latency_p95_ms: number;
      current_version_retrieval_count: string;
    }>(
      `SELECT retrieval_count::text, unique_principal_count::text,
              unique_agent_count::text, latency_p50_ms, latency_p95_ms,
              current_version_retrieval_count::text
         FROM analytics_daily_summary
        WHERE workspace_id = $1 AND day = $2::date AND skill_id = $3`,
      [tenant.workspaceId, day(retrievalAt), tenant.skillId],
    );
    expect(before.rows[0]).toMatchObject({
      retrieval_count: "10",
      unique_principal_count: "1",
      unique_agent_count: "1",
      latency_p50_ms: 14.5,
      current_version_retrieval_count: "10",
    });
    expect(before.rows[0]?.latency_p95_ms).toBeCloseTo(18.55);

    const retention = await runAuditRetention(pool, {
      now: new Date(),
      batchSize: 3,
    });
    expect(retention.deleted).toBe(10);
    expect(retention.batches).toBe(4);

    const detail = await pool.query<{ count: string }>(
      `SELECT count(*)::text AS count
         FROM audit_events
        WHERE workspace_id = $1 AND retention_class = 'detailed_read_90d'`,
      [tenant.workspaceId],
    );
    const permanent = await pool.query<{ event_type: string }>(
      `SELECT event_type FROM audit_events
        WHERE workspace_id = $1
          AND event_type IN (
            'skill.amendment.created',
            'oauth.refresh.reuse_detected'
          )
        ORDER BY event_type`,
      [tenant.workspaceId],
    );
    expect(detail.rows[0]?.count).toBe("0");
    expect(permanent.rows.map((row) => row.event_type)).toEqual([
      "oauth.refresh.reuse_detected",
      "skill.amendment.created",
      "skill.amendment.created",
    ]);

    const after = await pool.query<{ retrieval_count: string }>(
      `SELECT retrieval_count::text
         FROM analytics_daily_summary
        WHERE workspace_id = $1 AND day = $2::date AND skill_id = $3`,
      [tenant.workspaceId, day(retrievalAt), tenant.skillId],
    );
    expect(after.rows[0]?.retrieval_count).toBe("10");
  });

  it("never permits permanent security history through the retention trigger", async () => {
    await expect(
      pool.query(
        `DELETE FROM audit_events
          WHERE workspace_id = $1 AND event_type = 'oauth.refresh.reuse_detected'`,
        [tenant.workspaceId],
      ),
    ).rejects.toMatchObject({ code: "55000" });
  });

  it("preserves a full-day rollup across successive partial-day retention runs", async () => {
    const early = daysAgo(92, 2);
    const late = daysAgo(92, 20);
    for (const [label, occurredAt] of [
      ["early", early],
      ["late", late],
    ] as const) {
      await writeAuditEvent(pool, {
        id: `audit:partial-retention:${suffix}:${label}`,
        workspaceId: tenant.workspaceId,
        eventType: "mcp.skill_retrieve.success",
        action: "skill_retrieve",
        outcome: "success",
        actorType: "service_principal",
        actorId: "service:partial-retention",
        requestId: `request:partial-retention:${suffix}:${label}`,
        resourceType: "skill_version",
        resourceId: `skill-version:${suffix}`,
        skillId: tenant.skillId,
        versionId: `skill-version:${suffix}`,
        channel: "mcp",
        retentionClass: "detailed_read_90d",
        occurredAt,
      });
    }

    const firstCutoff = new Date(early);
    firstCutoff.setUTCHours(12, 0, 0, 0);
    const first = await runAuditRetention(pool, {
      now: new Date(firstCutoff.getTime() + 90 * 86_400_000),
    });
    expect(first.deleted).toBe(1);
    const preserved = await rollupUtcDay(pool, {
      day: day(early),
      workspaceId: tenant.workspaceId,
      preserveFullerSnapshot: true,
    });
    expect(preserved.sourceEvents).toBe(2);

    const secondCutoff = new Date(early);
    secondCutoff.setUTCDate(secondCutoff.getUTCDate() + 1);
    secondCutoff.setUTCHours(0, 0, 0, 0);
    const second = await runAuditRetention(pool, {
      now: new Date(secondCutoff.getTime() + 90 * 86_400_000),
    });
    expect(second.deleted).toBe(1);

    const retained = await pool.query<{
      event_count: string;
      source_event_count: string;
    }>(
      `SELECT dimension.event_count::text, run.source_event_count
         FROM analytics_daily_dimensions dimension
         JOIN analytics_rollup_runs run
           ON run.workspace_id = dimension.workspace_id
          AND run.day = dimension.day
        WHERE dimension.workspace_id = $1
          AND dimension.day = $2::date
          AND dimension.skill_id = ''
          AND dimension.dimension_type = 'tool'
          AND dimension.dimension_value = 'skill_retrieve'`,
      [tenant.workspaceId, day(early)],
    );
    expect(retained.rows[0]).toEqual({
      event_count: "2",
      source_event_count: "2",
    });
  });
});
import { Pool } from "pg";
import { expect, it } from "vitest";
import {
  rollupUtcDay,
  runAuditRetention,
  writeAuditEvent,
} from "@skillplane/observability";
import { migrateDatabase, resolveTestDatabaseUrl } from "@skillplane/db";

it("skips retained source data and maintains subsequent active workspaces", async () => {
  const name = `maintenance_${crypto.randomUUID().replaceAll("-", "").slice(0, 10)}_test`;
  const address = new URL(await resolveTestDatabaseUrl());
  address.pathname = "/postgres";
  const admin = new Pool({ connectionString: address.toString() });
  await admin.query(`CREATE DATABASE "${name}" TEMPLATE template0`);
  address.pathname = `/${name}`;
  const database = new Pool({ connectionString: address.toString(), max: 4 });
  const occurredAt = new Date(Date.now() - 100 * 86_400_000);
  try {
    await migrateDatabase(address.toString());
    for (const workspaceId of ["a-moved", "z-active"]) {
      await database.query(
        "INSERT INTO workspaces (id, workspace_id, slug, name) VALUES ($1, $1, $1, $1)",
        [workspaceId],
      );
      await writeAuditEvent(database, {
        workspaceId,
        eventType: "skill.retrieved",
        action: "skill:read",
        outcome: "success",
        actorType: "system",
        actorId: "system:matrix",
        requestId: crypto.randomUUID(),
        retentionClass: "detailed_read_90d",
        occurredAt,
      });
    }
    await database.query(`INSERT INTO regional_workspace_migration_fences
      (workspace_id, source_epoch, active_epoch) VALUES ('a-moved', 1, 1) ON CONFLICT (workspace_id) DO UPDATE SET source_epoch = 1`);
    await expect(
      rollupUtcDay(database, { day: occurredAt.toISOString().slice(0, 10) }),
    ).resolves.toMatchObject({
      workspaces: 1,
      sourceEvents: 1,
    });
    await expect(runAuditRetention(database, { dryRun: true })).resolves.toMatchObject({
      deleted: 1,
      affectedWorkspaces: ["z-active"],
    });
    await expect(runAuditRetention(database)).resolves.toMatchObject({
      deleted: 1,
      affectedWorkspaces: ["z-active"],
    });
    expect(
      (
        await database.query(
          "SELECT workspace_id FROM audit_events WHERE retention_class = 'detailed_read_90d'",
        )
      ).rows,
    ).toEqual([{ workspace_id: "a-moved" }]);
  } finally {
    await database.end();
    await admin.query(`DROP DATABASE "${name}" WITH (FORCE)`);
    await admin.end();
  }
}, 90_000);
import {
  assertDisposableDatabaseUrl,
  migrateDatabase,
  resolveTestDatabaseUrl,
} from "@skillplane/db";
import { Pool } from "pg";

/** Recreates only the explicitly named local test database, then migrates it. */
export async function resetTestDatabase(): Promise<string> {
  const databaseUrl = await resolveTestDatabaseUrl();
  assertDisposableDatabaseUrl(databaseUrl);
  const target = new URL(databaseUrl);
  const databaseName = target.pathname.slice(1);
  const adminUrl = new URL(databaseUrl);
  adminUrl.pathname = "/postgres";
  const pool = new Pool({
    connectionString: adminUrl.toString(),
    application_name: "skillplane-test-reset",
    max: 1,
  });
  try {
    await pool.query(
      `SELECT pg_terminate_backend(pid)
         FROM pg_stat_activity
        WHERE datname = $1 AND pid <> pg_backend_pid()`,
      [databaseName],
    );
    await pool.query(`DROP DATABASE IF EXISTS "${databaseName}"`);
    await pool.query(`CREATE DATABASE "${databaseName}" TEMPLATE template0`);
  } finally {
    await pool.end();
  }
  await migrateDatabase(databaseUrl);
  return databaseUrl;
}
