import { randomBytes } from 'node:crypto';
import type { AuthFnApiKeyRecord, AuthFnRuntimeConfig, AuthFnSession } from '../types.js';
import { AuthFnApiKeyRevokedError, AuthFnNotFoundError, AuthFnValidationError } from './errors.js';
import {
  AUTHFN_DATABASE_KEY_MAX_LENGTH,
  AUTHFN_LEGACY_USER_REFERENCE_MAX_LENGTH,
  assertAuthFnDatabaseKeyLength
} from './limits.js';
import { hashSecret } from './sessions.js';
import { findUserById } from './users.js';

export interface CreateApiKeyInput {
  userId: string;
  name: string;
  scopes?: string[];
  metadata?: Record<string, unknown>;
  expiresAt?: Date;
}

export interface CreatedApiKey {
  keyId: string;
  secret: string;
  record: AuthFnApiKeyRecord;
}

export interface SanitizedApiKey {
  id: string;
  userId?: string | null;
  name?: string;
  scopes?: string[];
  metadata?: Record<string, unknown>;
  expiresAt?: Date | null;
  revokedAt?: Date | null;
  lastUsedAt?: Date | null;
  createdAt: Date;
  updatedAt: Date;
}

export async function createApiKey(
  config: Pick<AuthFnRuntimeConfig, 'database' | 'namespace'>,
  input: CreateApiKeyInput,
  options?: { now?: () => Date; secretPrefix?: string }
): Promise<CreatedApiKey> {
  assertValidApiKeyName(input.name);
  assertValidApiKeyExpiry(input.expiresAt);
  const userIdLength = Array.from(input.userId).length;
  assertAuthFnDatabaseKeyLength(
    input.userId,
    'userId',
    AUTHFN_LEGACY_USER_REFERENCE_MAX_LENGTH
  );
  const legacyUser = userIdLength > AUTHFN_DATABASE_KEY_MAX_LENGTH
    ? await findUserById(config, input.userId)
    : null;
  const userId = legacyUser
    ? assertAuthFnDatabaseKeyLength(
        input.userId,
        'userId',
        AUTHFN_LEGACY_USER_REFERENCE_MAX_LENGTH
      )
    : assertAuthFnDatabaseKeyLength(input.userId, 'userId');
  const now = options?.now?.() ?? new Date();
  const secret = createApiKeySecret(options?.secretPrefix);
  const record: AuthFnApiKeyRecord = {
    id: createIdentifier('key'),
    userId,
    name: input.name,
    secretHash: hashSecret(secret),
    scopes: input.scopes,
    metadata: input.metadata,
    expiresAt: input.expiresAt ?? null,
    revokedAt: null,
    lastUsedAt: null,
    createdAt: now,
    updatedAt: now
  };

  await config.database.create<AuthFnApiKeyRecord>({
    model: 'api_keys',
    data: record,
    namespace: namespace(config)
  });

  return {
    keyId: record.id,
    secret,
    record
  };
}

export async function listApiKeysForUser(
  config: Pick<AuthFnRuntimeConfig, 'database' | 'namespace'>,
  userId: string
): Promise<SanitizedApiKey[]> {
  const records = await config.database.findMany<AuthFnApiKeyRecord>({
    model: 'api_keys',
    where: [{ field: 'userId', operator: 'eq', value: userId }],
    orderBy: [
      { field: 'createdAt', direction: 'asc' },
      { field: 'id', direction: 'asc' }
    ],
    namespace: namespace(config)
  });

  return records.map((record) => sanitizeApiKeyRecord(record));
}

export async function findApiKeyById(
  config: Pick<AuthFnRuntimeConfig, 'database' | 'namespace'>,
  keyId: string
): Promise<AuthFnApiKeyRecord | null> {
  return config.database.findOne<AuthFnApiKeyRecord>({
    model: 'api_keys',
    where: [{ field: 'id', operator: 'eq', value: keyId }],
    namespace: namespace(config)
  });
}

export async function revokeApiKeyById(
  config: Pick<AuthFnRuntimeConfig, 'database' | 'namespace'>,
  keyId: string,
  options?: { userId?: string; now?: () => Date }
): Promise<AuthFnApiKeyRecord> {
  const record = await findApiKeyById(config, keyId);
  if (!record || (options?.userId && record.userId !== options.userId)) {
    throw new AuthFnNotFoundError('API key not found', { keyId });
  }

  if (record.revokedAt) {
    return record;
  }

  const revokedAt = options?.now?.() ?? new Date();
  return config.database.update<AuthFnApiKeyRecord>({
    model: 'api_keys',
    where: [{ field: 'id', operator: 'eq', value: keyId }],
    data: {
      revokedAt,
      updatedAt: revokedAt
    },
    namespace: namespace(config)
  });
}

export async function authenticateApiKey(
  config: Pick<AuthFnRuntimeConfig, 'database' | 'namespace'>,
  secret: string,
  options?: { now?: () => Date }
): Promise<AuthFnSession | null> {
  const record = await config.database.findOne<AuthFnApiKeyRecord>({
    model: 'api_keys',
    where: [{ field: 'secretHash', operator: 'eq', value: hashSecret(secret) }],
    namespace: namespace(config)
  });

  if (!record) {
    return null;
  }

  if (record.revokedAt) {
    throw new AuthFnApiKeyRevokedError('API key has been revoked', {
      keyId: record.id
    });
  }

  const now = options?.now?.() ?? new Date();
  if (record.expiresAt && record.expiresAt.getTime() <= now.getTime()) {
    return null;
  }

  const updatedRecord = await config.database.update<AuthFnApiKeyRecord>({
    model: 'api_keys',
    where: [{ field: 'id', operator: 'eq', value: record.id }],
    data: {
      lastUsedAt: now,
      updatedAt: now
    },
    namespace: namespace(config)
  });

  return {
    id: updatedRecord.id,
    type: 'api-key',
    subject: {
      actorId: updatedRecord.id,
      actorType: 'api-key'
    },
    actorType: 'api-key',
    actorId: updatedRecord.id,
    resourceIds: [],
    methods: ['api-key'],
    expiresAt: updatedRecord.expiresAt ?? undefined,
    metadata: {
      ...(updatedRecord.metadata ?? {}),
      ownerUserId: updatedRecord.userId ?? undefined,
      scopes: updatedRecord.scopes ?? []
    }
  };
}

export function sanitizeApiKeyRecord(record: AuthFnApiKeyRecord): SanitizedApiKey {
  return {
    id: record.id,
    userId: record.userId,
    name: record.name,
    scopes: record.scopes,
    metadata: record.metadata,
    expiresAt: record.expiresAt ?? null,
    revokedAt: record.revokedAt ?? null,
    lastUsedAt: record.lastUsedAt ?? null,
    createdAt: record.createdAt,
    updatedAt: record.updatedAt
  };
}

function createApiKeySecret(prefix: string = 'ak'): string {
  return `${prefix}_${randomBytes(24).toString('base64url')}`;
}

function createIdentifier(prefix: string): string {
  return `${prefix}_${randomBytes(8).toString('hex')}`;
}

function namespace(config: Pick<AuthFnRuntimeConfig, 'namespace'>): string {
  return config.namespace ?? 'authfn';
}

function assertValidApiKeyName(name: string): void {
  if (typeof name !== 'string' || name.trim().length === 0) {
    throw new AuthFnValidationError('API key name is required', {
      field: 'name'
    });
  }

  const bytes = Buffer.byteLength(name, 'utf8');
  if (bytes > 128) {
    throw new AuthFnValidationError('API key name must be 128 UTF-8 bytes or fewer', {
      field: 'name',
      maxBytes: 128,
      receivedBytes: bytes
    });
  }
}

function assertValidApiKeyExpiry(expiresAt: Date | undefined): void {
  if (!expiresAt) {
    return;
  }

  if (!(expiresAt instanceof Date) || Number.isNaN(expiresAt.getTime())) {
    throw new AuthFnValidationError('API key expiry must be a valid date', {
      field: 'expiresAt'
    });
  }
}
import { describe, expect, it, vi } from 'vitest';
import { createTestServer } from './test-server.js';
import { memoryAdapter } from '../../../../packages/db/src/testing/index.js';
import { authFnApiKeyPlugin } from '@authfn/api-keys';
import type { AuthFnRuntimeConfig } from '../index.js';
import { issueSessionCookies } from '../core/cookies.js';
import { issueSession } from '../core/sessions.js';
import { createUser } from '../core/users.js';
import { createApiKey } from '../core/api-keys.js';

function createConfig(): AuthFnRuntimeConfig {
  return {
    database: memoryAdapter({ debug: false }),
    namespace: 'authfn',
    plugins: [
      authFnApiKeyPlugin()
    ],
    pluginRuntime: {
      apiKey: {
        now: () => new Date('2026-03-22T00:00:00.000Z')
      }
    }
  };
}

function cookieHeaderFromSetCookies(setCookies: string[]): string {
  return setCookies
    .map((cookie) => cookie.slice(0, cookie.indexOf(';')))
    .join('; ');
}

describe('authfn api key plugin', () => {
  it('rejects oversized user IDs in the exported persistence helper', async () => {
    const config = createConfig();

    await expect(createApiKey(config, {
      userId: 'u'.repeat(256),
      name: 'direct-helper'
    })).rejects.toMatchObject({
      code: 'AUTHFN_VALIDATION_ERROR',
      details: {
        fieldName: 'userId',
        maxLength: 255
      }
    });

    await expect(config.database.count({
      model: 'api_keys',
      namespace: 'authfn'
    })).resolves.toBe(0);
  });

  it('creates an API key for a persisted legacy oversized user ID', async () => {
    const config = createConfig();
    const userId = 'legacy-user-'.padEnd(300, 'x');
    await config.database.create({
      model: 'users',
      namespace: 'authfn',
      data: {
        id: userId,
        primaryEmail: 'legacy-api@example.com',
        createdAt: new Date(),
        updatedAt: new Date()
      }
    });

    const created = await createApiKey(config, {
      userId,
      name: 'legacy-key'
    });

    expect(created.record.userId).toBe(userId);
    await expect(config.database.count({
      model: 'api_keys',
      namespace: 'authfn'
    })).resolves.toBe(1);
  });

  it('rejects persisted legacy user IDs wider than the compatible reference column', async () => {
    const config = createConfig();
    const userId = 'legacy-user-'.padEnd(768, 'x');
    await config.database.create({
      model: 'users',
      namespace: 'authfn',
      data: {
        id: userId,
        createdAt: new Date(),
        updatedAt: new Date()
      }
    });
    const findOne = vi.spyOn(config.database, 'findOne');

    await expect(createApiKey(config, {
      userId,
      name: 'too-wide-legacy-key'
    })).rejects.toMatchObject({
      code: 'AUTHFN_VALIDATION_ERROR',
      details: { fieldName: 'userId', maxLength: 767 }
    });
    expect(findOne).not.toHaveBeenCalled();
  });

  it('creates, lists, authenticates, and revokes api keys with hashed secrets at rest', async () => {
    const config = createConfig();
    const auth = createTestServer(config);
    const user = await createUser(config, {
      primaryEmail: 'ada@example.com'
    });
    const issued = await issueSession(config, {}, {
      request: new Request('https://account.example.com/auth/session'),
      userId: user.id,
      primaryEmail: user.primaryEmail,
      methods: ['password']
    });
    const cookieHeader = cookieHeaderFromSetCookies(
      Object.values(issueSessionCookies(issued.cookiePolicy!, issued.sessionToken, issued.csrfToken))
    );

    const created = await auth.router.handle(
      new Request('https://account.example.com/auth/api-keys', {
        method: 'POST',
        headers: {
          cookie: cookieHeader,
          'content-type': 'application/json',
          'x-authfn-csrf': issued.csrfToken
        },
        body: JSON.stringify({
          name: 'server-to-server',
          scopes: ['read']
        })
      })
    );
    expect(created.status).toBe(201);
    const createdBody = await created.json();
    expect(createdBody.data.secretReturnedOnce).toBe(true);
    expect(createdBody.data.keyId).toEqual(expect.any(String));
    expect(createdBody.data.secret).toEqual(expect.stringMatching(/^ak_/));

    const stored = await config.database.findOne({
      model: 'api_keys',
      where: [{ field: 'id', operator: 'eq', value: createdBody.data.keyId }],
      namespace: 'authfn'
    });
    expect(stored?.secretHash).toBeDefined();
    expect(stored?.secretHash).not.toBe(createdBody.data.secret);

    const listed = await auth.router.handle(
      new Request('https://account.example.com/auth/api-keys', {
        headers: {
          cookie: cookieHeader
        }
      })
    );
    expect(listed.status).toBe(200);
    const listedBody = await listed.json();
    expect(listedBody.data.keys).toEqual([
      expect.objectContaining({
        id: createdBody.data.keyId,
        scopes: ['read']
      })
    ]);
    expect(JSON.stringify(listedBody)).not.toContain(createdBody.data.secret);

    const authenticated = await auth.provider.authenticate(
      new Request('https://account.example.com/auth/session', {
        headers: {
          authorization: `Bearer ${createdBody.data.secret}`
        }
      })
    );
    expect(authenticated?.type).toBe('api-key');
    expect(authenticated?.methods).toEqual(['api-key']);

    const revoked = await auth.router.handle(
      new Request(`https://account.example.com/auth/api-keys/${createdBody.data.keyId}`, {
        method: 'DELETE',
        headers: {
          cookie: cookieHeader,
          'x-authfn-csrf': issued.csrfToken
        }
      })
    );
    expect(revoked.status).toBe(200);
    expect((await revoked.json()).data).toEqual({
      revoked: true,
      keyId: createdBody.data.keyId
    });

    await expect(
      auth.provider.authenticate(
        new Request('https://account.example.com/auth/session', {
          headers: {
            authorization: `Bearer ${createdBody.data.secret}`
          }
        })
      )
    ).rejects.toMatchObject({
      code: 'AUTHFN_API_KEY_REVOKED'
    });
  });

  it('rejects api key names that exceed the canonical UTF-8 byte limit', async () => {
    const config = createConfig();
    const auth = createTestServer(config);
    const user = await createUser(config, {
      primaryEmail: 'ada@example.com'
    });
    const issued = await issueSession(config, {}, {
      request: new Request('https://account.example.com/auth/session'),
      userId: user.id,
      primaryEmail: user.primaryEmail,
      methods: ['password']
    });
    const cookieHeader = cookieHeaderFromSetCookies(
      Object.values(issueSessionCookies(issued.cookiePolicy!, issued.sessionToken, issued.csrfToken))
    );

    const rejected = await auth.router.handle(
      new Request('https://account.example.com/auth/api-keys', {
        method: 'POST',
        headers: {
          cookie: cookieHeader,
          'content-type': 'application/json',
          'x-authfn-csrf': issued.csrfToken
        },
        body: JSON.stringify({
          name: 'x'.repeat(129)
        })
      })
    );

    expect(rejected.status).toBe(400);
    expect((await rejected.json()).error.code).toBe('AUTHFN_VALIDATION_ERROR');
  });

  it('preserves authoritative metadata fields and rejects invalid expiry timestamps', async () => {
    const config = createConfig();
    const auth = createTestServer(config);
    const user = await createUser(config, {
      primaryEmail: 'ada@example.com'
    });
    const issued = await issueSession(config, {}, {
      request: new Request('https://account.example.com/auth/session'),
      userId: user.id,
      primaryEmail: user.primaryEmail,
      methods: ['password']
    });
    const cookieHeader = cookieHeaderFromSetCookies(
      Object.values(issueSessionCookies(issued.cookiePolicy!, issued.sessionToken, issued.csrfToken))
    );

    const invalidExpiry = await auth.router.handle(
      new Request('https://account.example.com/auth/api-keys', {
        method: 'POST',
        headers: {
          cookie: cookieHeader,
          'content-type': 'application/json',
          'x-authfn-csrf': issued.csrfToken
        },
        body: JSON.stringify({
          name: 'bad-expiry',
          expiresAt: 'not-a-date'
        })
      })
    );
    expect(invalidExpiry.status).toBe(400);
    expect((await invalidExpiry.json()).error.code).toBe('AUTHFN_VALIDATION_ERROR');

    const created = await auth.router.handle(
      new Request('https://account.example.com/auth/api-keys', {
        method: 'POST',
        headers: {
          cookie: cookieHeader,
          'content-type': 'application/json',
          'x-authfn-csrf': issued.csrfToken
        },
        body: JSON.stringify({
          name: 'authoritative',
          scopes: ['read'],
          metadata: {
            ownerUserId: 'override-attempt',
            scopes: ['override']
          }
        })
      })
    );
    const createdBody = await created.json();
    const authenticated = await auth.provider.authenticate(
      new Request('https://account.example.com/auth/session', {
        headers: {
          authorization: `Bearer ${createdBody.data.secret}`
        }
      })
    );

    expect(authenticated?.metadata).toMatchObject({
      ownerUserId: user.id,
      scopes: ['read']
    });
  });
});
