function createApiKeyRoutes(
  ctx: AuthFnPluginRuntimeContext,
  config: ApiKeyPluginConfig
): Route[] {
  const runtimeConfig = readPluginRuntimeConfig<ApiKeyPluginRuntimeConfig>(ctx, 'apiKey');

  return [
    {
      method: 'POST',
      path: '/api-keys',
      meta: createAuthFnRouteMeta('createApiKey', 'Create a new API key for the current user', {
        mode: 'cookie-session',
        csrf: true
      }),
      handler: async (request) => {
        const state = await requireCookieSession(ctx.config, request);
        assertValidCsrf(request, state);
        const body = await request.json() as {
          name?: string;
          scopes?: string[];
          metadata?: Record<string, unknown>;
          expiresAt?: string;
        };
        const created = await createApiKey(ctx.config, {
          userId: state.user.id,
          name: body.name ?? 'api-key',
          scopes: body.scopes,
          metadata: body.metadata,
          expiresAt: body.expiresAt ? new Date(body.expiresAt) : undefined
        }, {
          now: runtimeConfig.now,
          secretPrefix: config.secretPrefix
        });

        await emitAuthEvent(ctx.config, {
          type: 'authfn.api_key.created',
          requestId: eventRequestId(request),
          actorId: state.user.id,
          userId: state.user.id,
          outcome: 'created',
          metadata: {
            keyId: created.keyId,
            scopes: body.scopes ?? []
          }
        });

        return jsonSuccess(request, {
          keyId: created.keyId,
          secret: created.secret,
          secretReturnedOnce: true
        }, {
          status: 201
        });
      }
    },
    {
      method: 'GET',
      path: '/api-keys',
      meta: createAuthFnRouteMeta('listApiKeys', 'List API keys for the current user', {
        mode: 'cookie-session'
      }),
      handler: async (request) => {
        const state = await requireCookieSession(ctx.config, request);
        const keys = await listApiKeysForUser(ctx.config, state.user.id);
        return jsonSuccess(request, {
          keys
        });
      }
    },
    {
      method: 'DELETE',
      path: '/api-keys/:keyId',
      meta: createAuthFnRouteMeta('revokeApiKey', 'Revoke an API key for the current user', {
        mode: 'cookie-session',
        csrf: true
      }),
      handler: async (request, context) => {
        const state = await requireCookieSession(ctx.config, request);
        assertValidCsrf(request, state);
        await revokeApiKeyById(ctx.config, context.params.keyId, {
          userId: state.user.id,
          now: runtimeConfig.now
        });
        await emitAuthEvent(ctx.config, {
          type: 'authfn.api_key.revoked',
          requestId: eventRequestId(request),
          actorId: state.user.id,
          userId: state.user.id,
          outcome: 'revoked',
          metadata: {
            keyId: context.params.keyId
          }
        });
        return jsonSuccess(request, {
          revoked: true,
          keyId: context.params.keyId
        });
      }
    }
  ];
}
import { AuthFnValidationError } from './errors.js';

export const AUTHFN_DATABASE_KEY_MAX_LENGTH = 255;
// Keeps a user reference plus a TIMESTAMP within MySQL's 3072-byte utf8mb4
// composite-index limit (767 * 4 + 4).
export const AUTHFN_LEGACY_USER_REFERENCE_MAX_LENGTH = 767;

export function assertAuthFnDatabaseKeyLength(
  value: string,
  fieldName: string,
  maxLength: number = AUTHFN_DATABASE_KEY_MAX_LENGTH
): string {
  const length = Array.from(value).length;
  if (length > maxLength) {
    throw new AuthFnValidationError(
      `${fieldName} must contain at most ${maxLength} characters`,
      { fieldName, maxLength, actualLength: length }
    );
  }
  return value;
}
