  const claudeId = new URL("/client-metadata/claude", issuer).toString();
  const dcrId = "dcr-client";
  const supported = ["authorization_code", "refresh_token"];
  return [
    {
      id: "chatgpt-pre-registered-code-pkce",
      host: "chatgpt",
      registration: registration(chatgptId, "pre-registered", chatgptRedirect, supported),
      authorization: authorization(chatgptId, chatgptRedirect),
      token: {
        grantType: "authorization_code",
        refreshAfterExchange: true,
      },
      expected: { outcome: "allowed" },
    },
    {
      id: "claude-client-metadata-extensible-grants",
      host: "claude",
      registration: registration(claudeId, "client-metadata-document", claudeRedirect, [
        ...supported,
        "urn:ietf:params:oauth:grant-type:jwt-bearer",
        "urn:ietf:params:oauth:grant-type:device_code",
        "urn:example:params:oauth:grant-type:extension",
      ]),
      authorization: authorization(claudeId, claudeRedirect),
      token: {
        grantType: "authorization_code",
        refreshAfterExchange: true,
      },
      expected: { outcome: "allowed" },
    },
    {
      id: "dynamic-registration-code-pkce",
      host: "generic",
      registration: registration(dcrId, "dynamic", "http://127.0.0.1/callback", supported),
      authorization: authorization(dcrId, "http://127.0.0.1/callback"),
      token: { grantType: "authorization_code" },
      expected: { outcome: "allowed" },
    },
    {
      id: "chatgpt-unregistered-redirect",
      host: "chatgpt",
      registration: registration(chatgptId, "pre-registered", chatgptRedirect, supported),
      authorization: authorization(chatgptId, `${chatgptRedirect}/drift`),
      expected: {
        outcome: "rejected",
        errorCode: "invalid_request",
        phase: "authorization-request",
      },
    },
    {
      id: "incompatible-registration-grants",
      host: "generic",
      registration: registration(
        "incompatible-client",
        "pre-registered",
        "https://client.example.com/callback",
        ["urn:ietf:params:oauth:grant-type:jwt-bearer"],
      ),
      authorization: authorization(
        "incompatible-client",
        "https://client.example.com/callback",
      ),
      expected: {
        outcome: "rejected",
        errorCode: "invalid_client",
        phase: "authorization-request",
      },
    },
    {
      id: "actual-unsupported-token-grant",
      host: "generic",
      registration: registration(
        "unsupported-token-client",
        "pre-registered",
        "https://client.example.com/callback",
        supported,
      ),
      authorization: authorization(
        "unsupported-token-client",
        "https://client.example.com/callback",
      ),
      token: { grantType: "urn:example:unsupported-token-grant" },
      expected: {
        outcome: "rejected",
        errorCode: "unsupported_grant_type",
        phase: "token-exchange",
      },
    },
  ];
}

/** Run the independently-configured hosted-authorization matrix. */
export async function runHostedAuthorizationRegression(
  target: McpFnHostedAuthorizationTargetAdapter,
  fixtures: readonly McpFnHostedAuthorizationCase[],
): Promise<McpFnHostedAuthorizationCaseResult[]> {
  const results: McpFnHostedAuthorizationCaseResult[] = [];
  for (const fixture of fixtures) {
    results.push(await runHostedCase(target, fixture));
  }
  return results;
}

async function runHostedCase(
  target: McpFnHostedAuthorizationTargetAdapter,
  fixture: McpFnHostedAuthorizationCase,
): Promise<McpFnHostedAuthorizationCaseResult> {
  let phase: McpFnHostedAuthorizationCaseResult["phase"] = "client-registration";
  let responseStatus: number | undefined;
  try {
    await target.prepareRegistration(structuredClone(fixture.registration));
    phase = "authorization-request";
    const authorization = hostedAuthorizationUrl(target.issuer, fixture);
    responseStatus = undefined;
    const authorizationResponse = await target.request(new Request(authorization, {
      redirect: "manual",
    }));
    responseStatus = authorizationResponse.status;
    const authorizationError = await oauthError(authorizationResponse);
    if (authorizationError) {
      await validateOAuthRejection(authorizationResponse, fixture, target.issuer, "authorization");
      return assessHostedCase(fixture, phase, authorizationResponse.status, authorizationError);
    }
    if (!isRedirect(authorizationResponse.status)) {
      throw new Error(`Authorization request did not redirect (HTTP ${authorizationResponse.status})`);
    }
    const code = validatedRedirectCode(authorizationResponse, fixture, target.issuer);
    if (fixture.token) return runHostedTokenCase(target, fixture, fixture.token, code);
    return assessHostedCase(fixture, phase, responseStatus);
  } catch (error) {
    return assessHostedFailure(fixture, phase, responseStatus, error);
  }
}

async function runHostedTokenCase(
  target: McpFnHostedAuthorizationTargetAdapter,
  fixture: McpFnHostedAuthorizationCase,
  token: NonNullable<McpFnHostedAuthorizationCase["token"]>,
  code: string,
): Promise<McpFnHostedAuthorizationCaseResult> {
  let phase: McpFnHostedAuthorizationCaseResult["phase"] = token.grantType === "refresh_token"
    ? "token-refresh"
    : "token-exchange";
  let responseStatus: number | undefined;
  try {
    const tokenResponse = await target.request(hostedTokenRequest(
      target.issuer,
      tokenRequestBody(fixture, token, code),
    ));
    responseStatus = tokenResponse.status;
    const tokenError = await oauthError(tokenResponse);
    if (tokenError) {
      await validateOAuthRejection(tokenResponse, fixture, target.issuer, "token");
      return assessHostedCase(fixture, phase, responseStatus, tokenError);
    }
    if (!tokenResponse.ok) throw new Error(`Token request returned HTTP ${tokenResponse.status}`);
    const tokenSet = await validatedTokenSet(tokenResponse);
    if (!token.refreshAfterExchange) {
      return assessHostedCase(fixture, phase, responseStatus);
    }
    if (typeof tokenSet.refresh_token !== "string" || !tokenSet.refresh_token) {
      throw new Error("Authorization-code response did not include a refresh token");
    }
    phase = "token-refresh";
    responseStatus = undefined;
    const refreshBody = new URLSearchParams({
      grant_type: "refresh_token",
      client_id: fixture.authorization.clientId,
      refresh_token: tokenSet.refresh_token,
      resource: fixture.authorization.resource,
    });
    const refreshResponse = await target.request(hostedTokenRequest(target.issuer, refreshBody));
    responseStatus = refreshResponse.status;
    const refreshError = await oauthError(refreshResponse);
    if (refreshError) {
      await validateOAuthRejection(refreshResponse, fixture, target.issuer, "token");
      return assessHostedCase(fixture, phase, responseStatus, refreshError);
    }
    if (!refreshResponse.ok) {
      throw new Error(`Refresh request returned HTTP ${refreshResponse.status}`);
    }
    await validatedTokenSet(refreshResponse);
    return assessHostedCase(fixture, phase, responseStatus);
  } catch (error) {
    return assessHostedFailure(fixture, phase, responseStatus, error);
  }
}

function tokenRequestBody(
  fixture: McpFnHostedAuthorizationCase,
  token: NonNullable<McpFnHostedAuthorizationCase["token"]>,
  code: string,
): URLSearchParams {
  const body = new URLSearchParams({
    grant_type: token.grantType,
    client_id: fixture.authorization.clientId,
  });
  if (token.grantType === "authorization_code") {
    body.set("code", token.code ?? code);
    body.set("redirect_uri", fixture.authorization.redirectUri);
    body.set("code_verifier", fixture.authorization.codeVerifier);
    body.set("resource", fixture.authorization.resource);
  } else if (token.refreshToken) {
    body.set("refresh_token", token.refreshToken);
    body.set("resource", fixture.authorization.resource);
  }
  return body;
}

function hostedTokenRequest(issuer: string, body: URLSearchParams): Request {
  return new Request(new URL("token", ensureTrailingSlash(issuer)), {
    method: "POST",
    redirect: "manual",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body,
  });
}

function assessHostedFailure(
  fixture: McpFnHostedAuthorizationCase,
  phase: McpFnHostedAuthorizationCaseResult["phase"],
  responseStatus: number | undefined,
  error: unknown,
): McpFnHostedAuthorizationCaseResult {
  const redacted = redactOAuthValue(error);
  const safe = redacted && typeof redacted === "object"
    ? redacted as Record<string, unknown>
    : {};
  const code = typeof safe.code === "string" ? safe.code : undefined;
  const message = typeof safe.message === "string" ? safe.message : String(redacted);
  return assessHostedCase(
    fixture,
    phase,
    responseStatus,
    code,
    message || "Hosted adapter failed",
  );
}

function hostedAuthorizationUrl(
  issuer: string,
  fixture: McpFnHostedAuthorizationCase,
): URL {
  const authorization = new URL("authorize", ensureTrailingSlash(issuer));
  authorization.searchParams.set("response_type", "code");
  authorization.searchParams.set("client_id", fixture.authorization.clientId);
  authorization.searchParams.set("redirect_uri", fixture.authorization.redirectUri);
  authorization.searchParams.set(
    "code_challenge",
    derivePkceS256Challenge(fixture.authorization.codeVerifier),
  );
  authorization.searchParams.set("code_challenge_method", "S256");
  authorization.searchParams.set("state", fixture.authorization.state);
  authorization.searchParams.set("resource", fixture.authorization.resource);
  authorization.searchParams.set("scope", fixture.authorization.scopes.join(" "));
  return authorization;
}

function assessHostedCase(
  fixture: McpFnHostedAuthorizationCase,
  phase: McpFnHostedAuthorizationCaseResult["phase"],
  responseStatus?: number,
  errorCode?: string,
  error?: string,
): McpFnHostedAuthorizationCaseResult {
  const observedOutcome = errorCode || error ? "rejected" : "allowed";
  const expected = fixture.expected;
  const passed = !error && observedOutcome === expected.outcome &&
    (expected.errorCode === undefined || expected.errorCode === errorCode) &&
    (expected.phase === undefined || expected.phase === phase);
  const expectedCode = expected.errorCode ? `:${expected.errorCode}` : "";
  const observedCode = errorCode ? `:${errorCode}` : "";
  const mismatch = `Expected ${expected.outcome}${expectedCode}, received ${observedOutcome}${observedCode}`;
  return {
    formatVersion: 1,
    id: fixture.id,
    host: fixture.host,
    status: passed ? "passed" : "failed",
    phase,
    layer: phase === "client-registration" ? "mcpfn-preflight" : "authorization-server",
    ...(responseStatus === undefined ? {} : { responseStatus }),
    ...(errorCode ? { errorCode } : {}),
    ...(!passed || error ? {
      error: error ?? mismatch,
    } : {}),
  };
}

function isJsonResponse(response: Response): boolean {
  const mediaType = (response.headers.get("content-type") ?? "").split(";", 1)[0].trim().toLowerCase();
  return mediaType === "application/json" || /^application\/[a-z0-9!#$&^_.+-]+\+json$/.test(mediaType);
}

async function oauthError(response: Response): Promise<string | undefined> {
  const location = response.headers.get("location");
  if (location) {
    const code = new URL(location).searchParams.get("error");
    if (code) return code;
  }
  if (!isJsonResponse(response)) return undefined;
  const body = await response.clone().json().catch(() => undefined) as
    | { error?: unknown }
    | undefined;
  return typeof body?.error === "string" ? body.error : undefined;
}

async function validateOAuthRejection(
  response: Response,
  fixture: McpFnHostedAuthorizationCase,
  issuer: string,
  context: "authorization" | "token",
): Promise<void> {
  if (context === "authorization" && isRedirect(response.status)) {
    validateAuthorizationErrorRedirect(response, fixture, issuer);
    return;
  }
  const body = await response.clone().json().catch(() => undefined);
  const registered = (fixture.registration.metadata.redirect_uris as string[])
    ?.includes(fixture.authorization.redirectUri);
  if (context === "authorization" && body?.error !== "invalid_client" && registered) {
    throw new Error("Registered authorization requests require an OAuth error callback");
  }
  if (response.status !== 400) throw new Error("OAuth error response has invalid HTTP status");
  if (response.headers.has("location") || !isJsonResponse(response) ||
      !body || typeof body.error !== "string" || !body.error) {
    throw new Error("OAuth error response must be a JSON error envelope");
  }
}

function validateAuthorizationErrorRedirect(
  response: Response,
  fixture: McpFnHostedAuthorizationCase,
  issuer: string,
): void {
  const callback = new URL(response.headers.get("location") ?? "");
  // Redirects must target the registered URI, never a rejected requested URI.
  const registered = fixture.registration.metadata.redirect_uris as string[];
  if (!registered?.includes(fixture.authorization.redirectUri)) {
    throw new Error("Rejected redirect URI must not receive a callback");
  }
  const errors = callback.searchParams.getAll("error");
  if (errors.length !== 1 || !errors[0] || callback.searchParams.has("code")) {
    throw new Error("Invalid OAuth error callback");
  }
  if (errors[0] === "invalid_client") {
    throw new Error("Invalid-client authorization failures must not redirect");
  }
  callback.searchParams.delete("error");
  callback.searchParams.delete("error_description");
  callback.searchParams.delete("error_uri");
  callback.searchParams.set("code", "error-envelope-validation");
  validatedRedirectCode(
    new Response(null, { status: response.status, headers: { location: callback.toString() } }),
    fixture,
    issuer,
  );
}

function validatedRedirectCode(
  response: Response,
  fixture: McpFnHostedAuthorizationCase,
  issuer: string,
): string {
  const location = response.headers.get("location");
  if (!location) throw new Error("Authorization callback is missing");
  const callback = new URL(location);
  const expected = new URL(fixture.authorization.redirectUri);
  const codes = callback.searchParams.getAll("code");
  const states = callback.searchParams.getAll("state");
  if (codes.length !== 1 || !codes[0] || states.length !== 1 || states[0] !== fixture.authorization.state) {
    throw new Error("Authorization callback code or state is invalid");
  }
  const issuers = callback.searchParams.getAll("iss");
  if (issuers.length > 1 || (issuers.length === 1 && issuers[0] !== issuer)) {
    throw new Error("Authorization callback issuer is invalid");
  }
  if (callback.protocol !== expected.protocol || callback.host !== expected.host ||
      callback.username !== expected.username || callback.password !== expected.password ||
      callback.pathname !== expected.pathname || callback.hash !== expected.hash ||
      [...new Set(expected.searchParams.keys())].some((key) =>
        JSON.stringify(callback.searchParams.getAll(key)) !== JSON.stringify(expected.searchParams.getAll(key)))) {
    throw new Error("Authorization callback destination is invalid");
  }
  return codes[0];
}

async function validatedTokenSet(response: Response): Promise<{ refresh_token?: unknown }> {
  if (response.status !== 200) throw new Error("Successful token responses must use HTTP 200");
  if (!isJsonResponse(response)) throw new Error("Token response must use a JSON media type");
  if (!hasHeaderDirective(response.headers.get("cache-control"), "no-store") ||
      !hasHeaderDirective(response.headers.get("pragma"), "no-cache")) {
    throw new Error("Token responses must disable caching with Cache-Control: no-store and Pragma: no-cache");
  }
  const value = await response.clone().json() as Record<string, unknown> | null;
  if (!value || typeof value.access_token !== "string" || !/^[\dA-Za-z._~+/-]+=*$/.test(value.access_token) ||
      typeof value.token_type !== "string" || value.token_type.toLowerCase() !== "bearer") {
    throw new Error("Token response requires an access token and Bearer token type");
  }
  return value;
}

function hasHeaderDirective(value: string | null, expected: string): boolean {
  return (value ?? "").split(",").some((directive) =>
    directive.trim().toLowerCase() === expected,
  );
}

function isRedirect(status: number): boolean {
  return [301, 302, 303, 307, 308].includes(status);
}

function ensureTrailingSlash(value: string): URL {
  const url = new URL(value);
  if (!url.pathname.endsWith("/")) url.pathname += "/";
  return url;
}
","import type {
  CallToolResult,
  CreateTaskResult,
  GetPromptResult,
  ListTasksResult,
  ReadResourceResult,
  Task,
} from "@modelcontextprotocol/sdk/types.js";
import type { McpFnClientEvent, McpFnClientEventKind } from "@mcpfn/client";

import { McpFnAssertionError, assertStructuredTextParity, stableJson } from "./assertions.js";
import type { McpFnTestClient } from "./client.js";

export type McpFnScenarioSideEffect = "none" | "idempotent" | "non-idempotent";

export interface McpFnScenarioBase {
  formatVersion?: 1;
  name: string;
  /** Defaults to the runner timeout. */
  timeoutMs?: number;
  sideEffect?: McpFnScenarioSideEffect;
  status?: "complete" | "incomplete";
  incompleteReason?: string;
  /** Environment-backed placeholders used by this scenario, never their values. */
  variables?: string[];
}

export interface McpFnToolScenario extends McpFnScenarioBase {
  kind?: "tools.call";
  tool: string;
  arguments?: Record<string, unknown>;
  expect?: {
    isError?: boolean;
    structuredContent?: unknown;
    structuredTextParity?: boolean;
  };
  verify?(result: CallToolResult): void | Promise<void>;
}

export interface McpFnInventoryScenario extends McpFnScenarioBase {
  kind: "tools.list" | "resources.list" | "resources.templates.list" | "prompts.list";
  expectNames?: string[];
}

export interface McpFnResourceScenario extends McpFnScenarioBase {
  kind: "resources.read" | "resources.subscribe" | "resources.unsubscribe";
  uri: string;
  expect?: unknown;
}

export interface McpFnPromptScenario extends McpFnScenarioBase {
  kind: "prompts.get";
  prompt: string;
  arguments?: Record<string, string>;
  expect?: unknown;
}

export interface McpFnInitializeScenario extends McpFnScenarioBase {
  kind: "initialize";
  expectCapabilities?: Record<string, unknown>;
}

export interface McpFnCreateTaskScenario extends McpFnScenarioBase {
  kind: "tools.call:task";
  tool: string;
  arguments?: Record<string, unknown>;
  task?: { ttl?: number };
  expect?: unknown;
}

export interface McpFnTaskScenario extends McpFnScenarioBase {
  kind: "tasks.get" | "tasks.result" | "tasks.cancel" | "tasks.list";
  taskId?: string;
  cursor?: string;
  expect?: unknown;
}

export interface McpFnEventScenario extends McpFnScenarioBase {
  kind: "events.expect";
  event: McpFnClientEventKind;
  minimum?: number;
  expectPayload?: unknown;
}

export interface McpFnAuthScenario extends McpFnScenarioBase {
  kind: "auth.assert";
  phase: string;
  expect: {
    outcome: "allowed" | "denied";
    code?: string;
  };
  input?: Record<string, unknown>;
}

export type McpFnScenario =
  | McpFnToolScenario
  | McpFnInventoryScenario
  | McpFnResourceScenario
  | McpFnPromptScenario
  | McpFnInitializeScenario
  | McpFnCreateTaskScenario
  | McpFnTaskScenario
  | McpFnEventScenario
  | McpFnAuthScenario;

export interface McpFnScenarioArtifact {
  formatVersion: 1;
  kind: "mcpfn.scenarios";
  status: "complete" | "incomplete";
  scenarios: McpFnScenario[];
  variables?: string[];
  incompleteReason?: string;
}

export type McpFnRecordedOperation =
  | { kind: "tools.call"; name: string; arguments?: Record<string, unknown> }
  | { kind: "tools.call:task"; name: string; arguments?: Record<string, unknown>; task?: { ttl?: number } }
  | { kind: "resources.read"; uri: string }
  | { kind: "resources.subscribe"; uri: string }
  | { kind: "resources.unsubscribe"; uri: string }
  | { kind: "prompts.get"; name: string; arguments?: Record<string, string> }
  | { kind: "tasks.get"; taskId: string }
  | { kind: "tasks.result"; taskId: string }
  | { kind: "tasks.cancel"; taskId: string }
  | { kind: "tasks.list"; cursor?: string };

export type McpFnRecordedOperationResult =
  | CallToolResult
  | ReadResourceResult
  | GetPromptResult
  | CreateTaskResult
  | Task
  | ListTasksResult
  | void;

export interface McpFnScenarioResult {
  formatVersion: 1;
  name: string;
  operation: string;
  tool?: string;
  status: "passed" | "failed" | "incomplete";
  sideEffect: McpFnScenarioSideEffect;
  durationMs: number;
  error?: string;
  /** Observed client events discarded while this scenario was running. */
  droppedObservedEvents?: number;
  /** Dropped observed events whose original payload could not be safely redacted. */
  redactionOmittedObservedEvents?: number;
}

export interface McpFnScenarioReport {
  formatVersion: 1;
  kind: "mcpfn.scenario-report";
  status: "complete" | "incomplete";
  manifestHash?: string;
  total: number;
  passed: number;
  failed: number;
  incomplete: number;
  droppedResults: number;
  droppedObservedEvents: number;
  redactionOmittedObservedEvents?: number;
  incompleteReason?: string;
  results: McpFnScenarioResult[];
}

/** Convert an observed production-client operation into the shared runner contract. */
export function createMcpFnScenario(
  name: string,
  operation: McpFnRecordedOperation,
  result: McpFnRecordedOperationResult,
): McpFnScenario {
  switch (operation.kind) {
    case "tools.call":
      return createToolCallScenario(name, operation, result as CallToolResult);
    case "tools.call:task":
      return createToolTaskScenario(name, operation);
    case "resources.read":
      return createResourceReadScenario(name, operation, result);
    case "resources.subscribe":
    case "resources.unsubscribe":
      return createResourceLifecycleScenario(name, operation);
    case "tasks.get":
    case "tasks.cancel":
      return createTaskLifecycleScenario(name, operation);
    case "tasks.result":
      return createTaskResultScenario(name, operation, result);
    case "tasks.list":
      return createTaskListScenario(name, operation);
    case "prompts.get":
      return createPromptScenario(name, operation, result);
  }
}

function scenarioBase(name: string, sideEffect: McpFnScenarioSideEffect) {
  return { formatVersion: 1 as const, name, sideEffect };
}

function createToolCallScenario(
  name: string,
  operation: Extract<McpFnRecordedOperation, { kind: "tools.call" }>,
  result: CallToolResult,
): McpFnToolScenario {
  return {
    ...scenarioBase(name, "non-idempotent"),
    kind: "tools.call",
    tool: operation.name,
    ...(operation.arguments ? { arguments: operation.arguments } : {}),
    expect: {
      isError: Boolean(result.isError),
      ...(result.structuredContent !== undefined
        ? { structuredContent: result.structuredContent }
        : {}),
    },
  };
}

function createToolTaskScenario(
  name: string,
  operation: Extract<McpFnRecordedOperation, { kind: "tools.call:task" }>,
): McpFnCreateTaskScenario {
  return {
    ...scenarioBase(name, "non-idempotent"),
    kind: operation.kind,
    tool: operation.name,
    ...(operation.arguments ? { arguments: operation.arguments } : {}),
    ...(operation.task ? { task: operation.task } : {}),
  };
}

function createResourceReadScenario(
  name: string,
  operation: Extract<McpFnRecordedOperation, { kind: "resources.read" }>,
  result: McpFnRecordedOperationResult,
): McpFnResourceScenario {
  return {
    ...scenarioBase(name, "none"),
    kind: operation.kind,
    uri: operation.uri,
    expect: result,
  };
}

function createResourceLifecycleScenario(
  name: string,
  operation: Extract<McpFnRecordedOperation, { kind: "resources.subscribe" | "resources.unsubscribe" }>,
): McpFnResourceScenario {
  return {
    ...scenarioBase(name, "idempotent"),
    kind: operation.kind,
    uri: operation.uri,
  };
}

function createTaskLifecycleScenario(
  name: string,
  operation: Extract<McpFnRecordedOperation, { kind: "tasks.get" | "tasks.cancel" }>,
): McpFnTaskScenario {
  return {
    ...scenarioBase(name, operation.kind === "tasks.cancel" ? "idempotent" : "none"),
    kind: operation.kind,
    taskId: operation.taskId,
  };
}

function createTaskResultScenario(
  name: string,
  operation: Extract<McpFnRecordedOperation, { kind: "tasks.result" }>,
  result: McpFnRecordedOperationResult,
): McpFnTaskScenario {
  return {
    ...scenarioBase(name, "none"),
    kind: operation.kind,
    taskId: operation.taskId,
    expect: result,
  };
}

function createTaskListScenario(
  name: string,
  operation: Extract<McpFnRecordedOperation, { kind: "tasks.list" }>,
): McpFnTaskScenario {
  return {
    ...scenarioBase(name, "none"),
    kind: operation.kind,
    ...(operation.cursor ? { cursor: operation.cursor } : {}),
  };
}

function createPromptScenario(
  name: string,
  operation: Extract<McpFnRecordedOperation, { kind: "prompts.get" }>,
  result: McpFnRecordedOperationResult,
): McpFnPromptScenario {
  return {
    ...scenarioBase(name, "none"),
    kind: operation.kind,
    prompt: operation.name,
    ...(operation.arguments ? { arguments: operation.arguments } : {}),
    expect: result,
  };
}

/** Validate an unknown scenario module before it reaches the shared runner. */
export function validateMcpFnScenarios(value: unknown): McpFnScenario[] {
  const artifact = isScenarioArtifact(value) ? value : undefined;
  if (artifact?.status === "incomplete") {
    throw new Error(`McpFn scenario artifact is incomplete: ${artifact.incompleteReason}`);
  }
  const scenarios = artifact?.scenarios ?? value;
  if (!Array.isArray(scenarios)) {
    throw new TypeError("Scenario module must export an array or mcpfn.scenarios artifact");
  }
  for (const [index, scenario] of scenarios.entries()) {
    validateScenarioCandidate(scenario, index);
  }
  return scenarios as McpFnScenario[];
}

const SCENARIO_KINDS_WITHOUT_REQUIRED_FIELDS = new Set([
  "initialize",
  "tools.list",
  "resources.list",
  "resources.templates.list",
  "prompts.list",
  "tasks.list",
  "auth.assert",
]);

function validateScenarioCandidate(scenario: unknown, index: number): void {
  if (!scenario || typeof scenario !== "object" || Array.isArray(scenario)) {
    throw new TypeError(`Invalid scenario at index ${index}`);
  }
  const candidate = scenario as Record<string, unknown>;
  validateScenarioIdentity(candidate, index);
  const kind = scenarioKind(candidate, index);
  validateScenarioOperation(candidate, kind, index);
  validateScenarioLimits(candidate, index);
  if (kind === "events.expect") validateEventScenario(candidate, index);
  validateScenarioMetadata(candidate, index);
  if (kind === "auth.assert") validateAuthScenario(candidate, index);
}

function validateScenarioIdentity(candidate: Record<string, unknown>, index: number): void {
  if (candidate.formatVersion !== undefined && candidate.formatVersion !== 1) {
    throw new TypeError(`Invalid scenario at index ${index}: unsupported formatVersion`);
  }
  if (typeof candidate.name !== "string" || !candidate.name.trim()) {
    throw new TypeError(`Invalid scenario at index ${index}: name is required`);
  }
}

function scenarioKind(candidate: Record<string, unknown>, index: number): string {
  const kind = candidate.kind ?? "tools.call";
  if (typeof kind !== "string") {
    throw new TypeError(`Invalid scenario at index ${index}: kind must be a string`);
  }
  return kind;
}

function validateScenarioOperation(
  candidate: Record<string, unknown>,
  kind: string,
  index: number,
): void {
  const requiredField = requiredScenarioField(kind);
  if (requiredField && typeof candidate[requiredField] !== "string") {
    throw new TypeError(`Invalid scenario at index ${index}: ${kind} requires ${requiredField}`);
  }
  if (!requiredField && !SCENARIO_KINDS_WITHOUT_REQUIRED_FIELDS.has(kind)) {
    throw new TypeError(`Invalid scenario at index ${index}: unsupported kind ${kind}`);
  }
}

function validateScenarioLimits(candidate: Record<string, unknown>, index: number): void {
  if (
    candidate.timeoutMs !== undefined &&
    (!Number.isInteger(candidate.timeoutMs) || Number(candidate.timeoutMs) < 1 || Number(candidate.timeoutMs) > 300_000)
  ) {
    throw new TypeError(`Invalid scenario at index ${index}: timeoutMs must be 1..300000`);
  }
  if (
    candidate.variables !== undefined &&
    (
      !Array.isArray(candidate.variables) ||
      candidate.variables.some((entry) => typeof entry !== "string" || !/^[A-Z][A-Z0-9_]*$/.test(entry))
    )
  ) {
    throw new TypeError(`Invalid scenario at index ${index}: variables must be environment names`);
  }
}

function validateScenarioMetadata(candidate: Record<string, unknown>, index: number): void {
  if (
    candidate.status !== undefined &&
    candidate.status !== "complete" &&
    candidate.status !== "incomplete"
  ) {
    throw new TypeError(`Invalid scenario at index ${index}: status must be complete or incomplete`);
  }
  if (candidate.status === "incomplete" && typeof candidate.incompleteReason !== "string") {
    throw new TypeError(`Invalid scenario at index ${index}: incompleteReason is required`);
  }
  if (
    candidate.sideEffect !== undefined &&
    (typeof candidate.sideEffect !== "string" || !["none", "idempotent", "non-idempotent"].includes(candidate.sideEffect))
  ) {
    throw new TypeError(`Invalid scenario at index ${index}: sideEffect is unsupported`);
  }
}

function validateEventScenario(candidate: Record<string, unknown>, index: number): void {
  if (
    candidate.minimum !== undefined &&
    (!Number.isSafeInteger(candidate.minimum) || Number(candidate.minimum) < 1)
  ) {
    throw new TypeError(
      `Invalid scenario at index ${index}: events.expect minimum must be a positive integer`,
    );
  }
}

function validateAuthScenario(candidate: Record<string, unknown>, index: number): void {
  const expectation = candidate.expect as Record<string, unknown> | undefined;
  if (
    typeof candidate.phase !== "string" ||
    !expectation ||
    typeof expectation.outcome !== "string" ||
    !["allowed", "denied"].includes(expectation.outcome)
  ) {
    throw new TypeError(`Invalid scenario at index ${index}: auth.assert expectation is required`);
  }
}

export function createMcpFnScenarioArtifact(
  scenarios: McpFnScenario[],
  options?: Omit<McpFnScenarioArtifact, "formatVersion" | "kind" | "scenarios">,
): McpFnScenarioArtifact {
  const artifactOptions = options ?? { status: "complete" as const };
  return {
    formatVersion: 1,
    kind: "mcpfn.scenarios",
    ...artifactOptions,
    scenarios: validateMcpFnScenarios(scenarios),
  };
}

function isScenarioArtifact(value: unknown): value is McpFnScenarioArtifact {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const candidate = value as Record<string, unknown>;
  if (candidate.kind !== "mcpfn.scenarios") return false;
  if (candidate.formatVersion !== 1) {
    throw new Error("Unsupported McpFn scenario artifact formatVersion");
  }
  if (candidate.status !== "complete" && candidate.status !== "incomplete") {
    throw new Error("McpFn scenario artifact status must be complete or incomplete");
  }
  if (candidate.status === "incomplete" && typeof candidate.incompleteReason !== "string") {
    throw new Error("Incomplete McpFn scenario artifact requires incompleteReason");
  }
  return true;
}

export async function runScenarios(
  client: McpFnTestClient<unknown>,
  scenarios: McpFnScenario[],
  options: McpFnScenarioRunOptions = {},
): Promise<McpFnScenarioResult[]> {
  if (
    options.defaultTimeoutMs !== undefined &&
    (
      !Number.isInteger(options.defaultTimeoutMs) ||
      options.defaultTimeoutMs < 1 ||
      options.defaultTimeoutMs > 300_000
    )
  ) {
    throw new Error("defaultTimeoutMs must be an integer from 1 through 300000");
  }
  if (
    options.maxScenarios !== undefined &&
    (!Number.isInteger(options.maxScenarios) || options.maxScenarios < 1)
  ) {
    throw new Error("maxScenarios must be a positive integer");
  }
  if (
    options.maxErrorBytes !== undefined &&
    (!Number.isInteger(options.maxErrorBytes) || options.maxErrorBytes < 64)
  ) {
    throw new Error("maxErrorBytes must be an integer of at least 64");
  }
  if (
    options.maxObservedEvents !== undefined &&
    (!Number.isInteger(options.maxObservedEvents) || options.maxObservedEvents < 1)
  ) {
    throw new Error("maxObservedEvents must be a positive integer");
  }
  if (scenarios.length > (options.maxScenarios ?? 1_000)) {
    throw new Error(`Scenario count exceeds the configured cap of ${options.maxScenarios ?? 1_000}`);
  }
  const results: McpFnScenarioResult[] = [];
  const observedEvents: McpFnClientEvent[] = [];
  const maxObservedEvents = options.maxObservedEvents ?? 500;
  let droppedObservedEvents = 0;
  let redactionOmittedObservedEvents = 0;
  let observedRedactionOmissionEvents = 0;
  let attributedDroppedObservedEvents = 0;
  let attributedRedactionOmittedObservedEvents = 0;
  const initialClientEventRedactionOmissions = client.session
    .getRedactionOmissionCounts().clientEvents;
  const pushResult = (result: McpFnScenarioResult): void => {
    const newlyDropped = droppedObservedEvents - attributedDroppedObservedEvents;
    const newlyRedactionOmitted = redactionOmittedObservedEvents -
      attributedRedactionOmittedObservedEvents;
    results.push({
      ...result,
      ...(newlyDropped > 0
        ? { droppedObservedEvents: (result.droppedObservedEvents ?? 0) + newlyDropped }
        : {}),
      ...(newlyRedactionOmitted > 0
        ? {
          redactionOmittedObservedEvents:
            (result.redactionOmittedObservedEvents ?? 0) + newlyRedactionOmitted,
        }
        : {}),
    });
    attributedDroppedObservedEvents = droppedObservedEvents;
    attributedRedactionOmittedObservedEvents = redactionOmittedObservedEvents;
  };
  const unsubscribe = client.session.onEvent((event) => {
    if (client.session.isRedactionOmission(event)) {
      observedRedactionOmissionEvents += 1;
      droppedObservedEvents += 1;
      redactionOmittedObservedEvents += 1;
      return;
    }
    observedEvents.push(event);
    if (observedEvents.length > maxObservedEvents) {
      observedEvents.shift();
      droppedObservedEvents += 1;
    }
  });
  let timedOutScenario: string | undefined;
  try {
    for (const scenario of scenarios) {
      const startedAt = performance.now();
      const operation = scenario.kind ?? "tools.call";
      const common = {
        formatVersion: 1 as const,
        name: scenario.name,
        operation,
        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
        sideEffect: scenario.sideEffect ?? defaultSideEffect(operation),
      };
      if (timedOutScenario) {
        pushResult({
          ...common,
          status: "incomplete",
          durationMs: 0,
          error: truncateError(`Skipped after timed-out scenario: ${timedOutScenario}`, options, client),
        });
        continue;
      }
      const resolved = resolveScenarioVariables(scenario, options.variables);
      if (resolved.missing.length > 0) {
        pushResult({
          ...common,
          status: "incomplete",
          durationMs: 0,
          error: truncateError(
            `Missing scenario variables: ${resolved.missing.join(", ")}`,
            options,
            client,
          ),
        });
        continue;
      }
      if (scenario.status === "incomplete") {
        pushResult({
          ...common,
          status: "incomplete",
          durationMs: 0,
          error: truncateError(scenario.incompleteReason ?? "Scenario is incomplete", options, client),
        });
        continue;
      }
      const timeoutMs = scenario.timeoutMs ?? options.defaultTimeoutMs ?? 30_000;
      const controller = new AbortController();
      let timer: ReturnType<typeof setTimeout> | undefined;
      let timedOut = false;
      try {
        await Promise.race([
          executeScenario(client, resolved.scenario, {
            signal: controller.signal,
            timeout: timeoutMs,
          }, observedEvents, options),
          new Promise<never>((_resolve, reject) => {
            timer = setTimeout(() => {
              timedOut = true;
              controller.abort();
              reject(new McpFnAssertionError(`Scenario timed out after ${timeoutMs}ms`));
            }, timeoutMs);
          }),
        ]);
        pushResult({
          ...common,
          status: "passed",
          durationMs: performance.now() - startedAt,
        });
      } catch (error) {
        pushResult({
          ...common,
          status: "failed",
          durationMs: performance.now() - startedAt,
          error: truncateError(error instanceof Error ? error.message : String(error), options, client),
        });
        if (timedOut) timedOutScenario = scenario.name;
      } finally {
        if (timer) clearTimeout(timer);
      }
    }
  } finally {
    const unobservedRedactionOmissions = Math.max(
      0,
      client.session.getRedactionOmissionCounts().clientEvents -
        initialClientEventRedactionOmissions - observedRedactionOmissionEvents,
    );
    droppedObservedEvents += unobservedRedactionOmissions;
    redactionOmittedObservedEvents += unobservedRedactionOmissions;
    const unattributed = droppedObservedEvents - attributedDroppedObservedEvents;
    const lastResult = results.at(-1);
    if (lastResult && unattributed > 0) {
      lastResult.droppedObservedEvents =
        (lastResult.droppedObservedEvents ?? 0) + unattributed;
    }
    const unattributedRedaction = redactionOmittedObservedEvents -
      attributedRedactionOmittedObservedEvents;
    if (lastResult && unattributedRedaction > 0) {
      lastResult.redactionOmittedObservedEvents =
        (lastResult.redactionOmittedObservedEvents ?? 0) + unattributedRedaction;
    }
    unsubscribe();
  }
  return results;
}

export interface McpFnScenarioRunOptions {
  defaultTimeoutMs?: number;
  maxScenarios?: number;
  maxErrorBytes?: number;
  /** Observed client-event count cap. Defaults to 500. */
  maxObservedEvents?: number;
  variables?: Record<string, string | undefined>;
  auth?(scenario: McpFnAuthScenario, signal: AbortSignal): Promise<{
    outcome: "allowed" | "denied";
    code?: string;
  }>;
}

function resolveScenarioVariables(
  scenario: McpFnScenario,
  supplied: Record<string, string | undefined> | undefined,
): { scenario: McpFnScenario; missing: string[] } {
  const values = { ...process.env, ...supplied };
  const required = new Set(scenario.variables ?? []);
  const marker = /\$\{([A-Z][A-Z0-9_]*)\}/g;
  const encodedMarker = /%24%7[Bb]([A-Z][A-Z0-9_]*)%7[Dd]/g;
  const visitString = (value: string): string => {
    for (const match of value.matchAll(marker)) required.add(match[1]);
    for (const match of value.matchAll(encodedMarker)) required.add(match[1]);
    return value
      .replace(marker, (original, name: string) => values[name] ?? original)
      .replace(encodedMarker, (original, name: string) =>
        values[name] === undefined ? original : encodeURIComponent(values[name]),
      );
  };
  const visit = (value: unknown): unknown => {
    if (typeof value === "string") return visitString(value);
    if (Array.isArray(value)) return value.map(visit);
    if (value && typeof value === "object") {
      const entries: Array<[string, unknown]> = [];
      const keys = new Set<string>();
      for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
        const resolvedKey = visitString(key);
        if (keys.has(resolvedKey)) {
          throw new Error("Scenario variable substitution creates duplicate object key");
        }
        keys.add(resolvedKey);
        entries.push([resolvedKey, visit(entry)]);
      }
      return Object.fromEntries(entries);
    }
    return value;
  };
  const resolved = visit(scenario) as McpFnScenario;
  return {
    scenario: resolved,
    missing: [...required]
      .filter((name) => values[name] === undefined)
      .sort(compareCodeUnits),
  };
}

export function createMcpFnScenarioReport(
  results: McpFnScenarioResult[],
  options: { manifestHash?: string; maxBytes?: number } = {},
): McpFnScenarioReport {
  const failed = results.filter((result) => result.status === "failed").length;
  const incomplete = results.filter((result) => result.status === "incomplete").length;
  const droppedObservedEvents = results.reduce(
    (total, result) => total + (result.droppedObservedEvents ?? 0),
    0,
  );
  const redactionOmittedObservedEvents = results.reduce(
    (total, result) => total + (result.redactionOmittedObservedEvents ?? 0),
    0,
  );
  const overflowedObservedEvents = droppedObservedEvents - redactionOmittedObservedEvents;
  const report: McpFnScenarioReport = {
    formatVersion: 1,
    kind: "mcpfn.scenario-report",
    status: incomplete === 0 && droppedObservedEvents === 0 ? "complete" : "incomplete",
    ...(options.manifestHash ? { manifestHash: options.manifestHash } : {}),
    total: results.length,
    passed: results.length - failed - incomplete,
    failed,
    incomplete,
    droppedResults: 0,
    droppedObservedEvents,
    ...(redactionOmittedObservedEvents > 0 ? { redactionOmittedObservedEvents } : {}),
    ...(droppedObservedEvents > 0
      ? {
        incompleteReason: [
          ...(redactionOmittedObservedEvents > 0
            ? ["Observed client events were omitted because credential redaction failed"]
            : []),
          ...(overflowedObservedEvents > 0
            ? ["Observed client events exceeded maxObservedEvents"]
            : []),
        ].join("; "),
      }
      : {}),
    results: structuredClone(results),
  };
  const maxBytes = options.maxBytes ?? 1_048_576;
  if (!Number.isInteger(maxBytes) || maxBytes < 1_024) {
    throw new Error("maxBytes must be an integer of at least 1024");
  }
  if (serializedBytes(report) > maxBytes) {
    report.status = "incomplete";
    report.incompleteReason = "Report content exceeded maxBytes and was truncated";
  }
  while (serializedBytes(report) > maxBytes && report.results.length > 0) {
    report.results.pop();
    report.droppedResults += 1;
  }
  if (report.droppedResults > 0) {
    report.status = "incomplete";
  }
  if (serializedBytes(report) > maxBytes) {
    throw new Error("The minimum scenario report exceeds maxBytes");
  }
  return report;
}

function serializedBytes(value: unknown): number {
  return new TextEncoder().encode(JSON.stringify(value)).byteLength;
}

async function executeScenario(
  client: McpFnTestClient<unknown>,
  scenario: McpFnScenario,
  requestOptions: { signal: AbortSignal; timeout: number },
  observedEvents: McpFnClientEvent[],
  runOptions: McpFnScenarioRunOptions,
): Promise<void> {
  const kind = scenario.kind ?? "tools.call";
  if (isInventoryScenario(scenario)) {
    await executeInventoryScenario(client, scenario, requestOptions);
    return;
  }
  switch (scenario.kind) {
    case undefined:
    case "tools.call":
      return executeToolScenario(client, scenario, requestOptions);
    case "initialize":
      return executeInitializeScenario(client, scenario);
    case "resources.read":
      return assertExpectedAsync(client.readResource(scenario.uri, requestOptions), scenario.expect);
    case "resources.subscribe":
      return client.subscribeResource(scenario.uri, requestOptions);
    case "resources.unsubscribe":
      return client.unsubscribeResource(scenario.uri, requestOptions);
    case "prompts.get":
      return assertExpectedAsync(
        client.getPrompt(scenario.prompt, scenario.arguments, requestOptions),
        scenario.expect,
      );
    case "tools.call:task":
      return assertExpectedAsync(
        client.createToolTask(scenario.tool, scenario.arguments, scenario.task, requestOptions),
        scenario.expect,
      );
    case "tasks.get":
      return assertExpectedAsync(client.getTask(scenario.taskId!, requestOptions), scenario.expect);
    case "tasks.result":
      return assertExpectedAsync(client.getTaskResult(scenario.taskId!, requestOptions), scenario.expect);
    case "tasks.cancel":
      return assertExpectedAsync(client.cancelTask(scenario.taskId!, requestOptions), scenario.expect);
    case "tasks.list":
      return assertExpectedAsync(client.listTasks(scenario.cursor, requestOptions), scenario.expect);
    case "events.expect":
      return executeEventScenario(scenario, observedEvents);
    case "auth.assert":
      return executeAuthScenario(scenario, requestOptions.signal, runOptions);
  }
  throw new McpFnAssertionError(`Unsupported scenario operation ${kind}`);
}

async function executeToolScenario(
  client: McpFnTestClient<unknown>,
  scenario: McpFnToolScenario,
  requestOptions: { signal: AbortSignal; timeout: number },
): Promise<void> {
  const result = await client.callTool(
    scenario.tool,
    scenario.arguments,
    requestOptions,
  );
  assertToolResult(result, scenario);
  await scenario.verify?.(result);
}

function assertToolResult(result: CallToolResult, scenario: McpFnToolScenario): void {
  if (result.isError && scenario.expect?.isError === undefined) {
    throw new McpFnAssertionError(
      "Tool returned isError=true without an explicit expect.isError=true assertion",
    );
  }
  if (
    scenario.expect?.isError !== undefined &&
    Boolean(result.isError) !== scenario.expect.isError
  ) {
    throw new McpFnAssertionError(
      `Expected isError=${scenario.expect.isError}, received ${Boolean(result.isError)}`,
    );
  }
  if (
    scenario.expect &&
    Object.hasOwn(scenario.expect, "structuredContent") &&
    stableJson(result.structuredContent) !== stableJson(scenario.expect.structuredContent)
  ) {
    throw new McpFnAssertionError(
      `Structured result mismatch\nexpected: ${stableJson(scenario.expect.structuredContent)}\nactual:   ${stableJson(result.structuredContent)}`,
    );
  }
  if (scenario.expect?.structuredTextParity) assertStructuredTextParity(result);
}

function executeInitializeScenario(
  client: McpFnTestClient<unknown>,
  scenario: McpFnInitializeScenario,
): void {
  const actual = client.client.getServerCapabilities() ?? {};
  if (scenario.expectCapabilities && stableJson(actual) !== stableJson(scenario.expectCapabilities)) {
    throw new McpFnAssertionError(
      `Capability mismatch\nexpected: ${stableJson(scenario.expectCapabilities)}\nactual:   ${stableJson(actual)}`,
    );
  }
}

async function executeInventoryScenario(
  client: McpFnTestClient<unknown>,
  scenario: McpFnInventoryScenario,
  requestOptions: { signal: AbortSignal; timeout: number },
): Promise<void> {
  const values = await listScenarioInventory(client, scenario.kind, requestOptions);
  if (!scenario.expectNames) return;
  const actual = values.map((value) => value.name).sort(compareCodeUnits);
  const expected = [...scenario.expectNames].sort(compareCodeUnits);
  if (stableJson(actual) !== stableJson(expected)) {
    throw new McpFnAssertionError(
      `Inventory mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
    );
  }
}

async function assertExpectedAsync(actual: Promise<unknown>, expected: unknown): Promise<void> {
  assertExpected(await actual, expected);
}

function executeEventScenario(
  scenario: McpFnEventScenario,
  observedEvents: McpFnClientEvent[],
): void {
  const matching = observedEvents.filter((event) => event.kind === scenario.event);
  if (matching.length < (scenario.minimum ?? 1)) {
    throw new McpFnAssertionError(
      `Expected at least ${scenario.minimum ?? 1} ${scenario.event} event(s), received ${matching.length}`,
    );
  }
  if (scenario.expectPayload !== undefined) {
    assertExpected(matching.at(-1)?.payload, scenario.expectPayload);
  }
}

async function executeAuthScenario(
  scenario: McpFnAuthScenario,
  signal: AbortSignal,
  runOptions: McpFnScenarioRunOptions,
): Promise<void> {
  if (!runOptions.auth) {
    throw new McpFnAssertionError("auth.assert requires a scenario auth adapter");
  }
  assertExpected(await runOptions.auth(scenario, signal), scenario.expect);
}

function truncateError(value: string, options: McpFnScenarioRunOptions, client: McpFnTestClient): string {
  let redacted = "Scenario error omitted because credential redaction failed";
  try { redacted = String(client.session.redact(value)); }
  catch { /* Report safely even when a diagnostic exceeds the redaction budget. */ }
  const maxBytes = options.maxErrorBytes ?? 4_096;
  const bytes = new TextEncoder().encode(redacted);
  if (bytes.byteLength <= maxBytes) return redacted;
  return `${new TextDecoder().decode(bytes.slice(0, Math.max(0, maxBytes - 16)))}...[TRUNCATED]`;
}

function defaultSideEffect(operation: string): McpFnScenarioSideEffect {
  if (operation === "tools.call" || operation === "tools.call:task") {
    return "non-idempotent";
  }
  if (operation === "tasks.cancel") return "idempotent";
  return "none";
}

function compareCodeUnits(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

function assertExpected(actual: unknown, expected: unknown): void {
  if (expected !== undefined && stableJson(actual) !== stableJson(expected)) {
    throw new McpFnAssertionError(
      `Scenario result mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
    );
  }
}

function isToolScenario(scenario: McpFnScenario): scenario is McpFnToolScenario {
  return "tool" in scenario;
}

function isInventoryScenario(scenario: McpFnScenario): scenario is McpFnInventoryScenario {
  return ["tools.list", "resources.list", "resources.templates.list", "prompts.list"]
    .includes(scenario.kind ?? "");
}

function requiredScenarioField(kind: string): string | undefined {
  switch (kind) {
    case "tools.call":
    case "tools.call:task":
      return "tool";
    case "resources.read":
    case "resources.subscribe":
    case "resources.unsubscribe":
      return "uri";
    case "prompts.get":
      return "prompt";
    case "tasks.get":
    case "tasks.result":
    case "tasks.cancel":
      return "taskId";
    case "events.expect":
      return "event";
    default:
      return undefined;
  }
}

async function listScenarioInventory(
  client: McpFnTestClient<unknown>,
  kind: McpFnInventoryScenario["kind"],
  requestOptions: { signal: AbortSignal; timeout: number },
) {
  switch (kind) {
    case "tools.list":
      return client.listTools(requestOptions);
    case "resources.list":
      return client.listResources(requestOptions);
    case "resources.templates.list":
      return client.listResourceTemplates(requestOptions);
    case "prompts.list":
      return client.listPrompts(requestOptions);
  }
}
","import {
  McpFnRedactionLimitError,
  McpFnStructuralCredentialCollisionError,
  beginTargetCredentialRedaction,
  redactTargetCredentials,
} from "./remote-target.js";
import type { Implementation, ServerCapabilities } from "@modelcontextprotocol/sdk/types.js";
import {
  McpFnClientError,
  type McpFnDiagnosticEvent,
  type McpFnTarget,
  type McpFnTargetDescriptor,
} from "@mcpfn/client";
import type { McpFnManifest } from "@mcpfn/core";

import { assertManifestContract, McpFnAssertionError, stableJson } from "./assertions.js";
import {
  McpFnTestClient,
  McpFnTestClientCleanupError,
  type McpFnTestClientOptions,
} from "./client.js";
import {
  MCPFN_REPORT_SCHEMA_VERSION,
  MCPFN_TESTING_VERSION,
  normalizeMcpFnReportFailure,
  type McpFnReportFailure,
} from "./reports.js";
import {
  disposeMcpFnTargetSuiteArtifactGuard,
  preserveMcpFnTargetSuiteArtifact,
  registerMcpFnTargetSuiteArtifactGuard,
} from "./artifact-guards.js";
import {
  runScenarios,
  type McpFnScenario,
  type McpFnScenarioResult,
} from "./scenarios.js";

export interface RunMcpFnTargetSuiteOptions {
  target: McpFnTarget;
  scenarios?: McpFnScenario[];
  manifest?: McpFnManifest;
  expectedToolNames?: readonly string[];
  clientInfo?: Implementation;
  client?: McpFnTestClientOptions;
  scenarioRun?: NonNullable<Parameters<typeof runScenarios>[2]>;
  /** Aggregate JSON size cap. Defaults to 1 MiB. */
  maxReportBytes?: number;
  /** Diagnostic timeline count cap. Defaults to 500. */
  maxTimelineEvents?: number;
}

export interface McpFnTargetSuiteReport {
  formatVersion: 1;
  kind: "mcpfn.target-suite-report";
  /** Generated reports require retained target proof for derived encodings. */
  artifactValidation?: "target-aware";
  status: "complete" | "incomplete";
  runtime: {
    node: string;
    scenarioFormatVersion: 1;
    reportSchemaVersion: string;
    packages: { testing: string };
  };
  ok: boolean;
  target: McpFnTargetDescriptor;
  server?: Implementation;
  capabilities?: ServerCapabilities;
  manifestChecked: boolean;
  manifestHash?: string;
  total: number;
  passed: number;
  failed: number;
  incomplete: number;
  droppedResults: number;
  droppedObservedEvents: number;
  redactionOmittedObservedEvents?: number;
  incompleteReason?: string;
  failure?: McpFnReportFailure;
  timeline: McpFnDiagnosticEvent[];
  droppedTimelineEvents: number;
  results: McpFnScenarioResult[];
}

const suiteCleanupOwners = new WeakMap<Error, { close: () => Promise<void>; pending?: Promise<void> }>();

function retryTargetSuiteCleanup(error: Error): Promise<void> {
  const owner = suiteCleanupOwners.get(error);
  if (!owner) return Promise.resolve();
  if (owner.pending) return owner.pending;
  const pending = Promise.resolve().then(owner.close).then(
    () => { suiteCleanupOwners.delete(error); },
    () => { throw error; },
  ).finally(() => { owner.pending = undefined; });
  owner.pending = pending;
  return pending;
}

/** Final cleanup failed. The bounded report is a snapshot; retain this error to retry. */
export class McpFnTargetSuiteCleanupError extends Error {
  constructor(readonly report: McpFnTargetSuiteReport, close: () => Promise<void>) {
    super("Target suite cleanup failed; retain this error and retryCleanup()");
    this.name = "McpFnTargetSuiteCleanupError";
    suiteCleanupOwners.set(this, { close });
  }

  retryCleanup(): Promise<void> {
    return retryTargetSuiteCleanup(this);
  }
}

/** Report serialization failed after cleanup ownership had already transferred. */
export class McpFnTargetSuiteArtifactCleanupError extends Error {
  constructor(close: () => Promise<void>, cause: Error) {
    super(`${cause.message}; retain this error and retryCleanup()`, { cause });
    this.name = "McpFnTargetSuiteArtifactCleanupError";
    suiteCleanupOwners.set(this, { close });
  }

  retryCleanup(): Promise<void> {
    return retryTargetSuiteCleanup(this);
  }
}

/** Runs local, stdio, HTTP, or custom targets through the production session engine. */
export async function runMcpFnTargetSuite(
  options: RunMcpFnTargetSuiteOptions,
): Promise<McpFnTargetSuiteReport> {
  const artifactRedaction = beginSuiteArtifactRedaction(options.target);
  let finishRedaction = artifactRedaction.finish;
  const retainArtifactGuard = (report: McpFnTargetSuiteReport) => {
    registerMcpFnTargetSuiteArtifactGuard(
      report,
      artifact => {
        if (!artifactRedaction.retained) return false;
        if (options.target.assertArtifactSafe) {
          options.target.assertArtifactSafe(artifact);
          return true;
        }
        // Built-in unauthenticated targets do not own credential material.
        // Custom targets that do own it must expose either the exact validator
        // above or a redactor that can prove the completed artifact unchanged.
        if (!options.target.redact) return true;
        return Object.is(
          redactSuiteArtifact(options.target, artifact, { preserveKeys: false }),
          artifact,
        );
      },
      finishRedaction,
      options.maxReportBytes ?? 1_048_576,
    );
    finishRedaction = () => undefined;
    try {
      preserveMcpFnTargetSuiteArtifact(report, JSON.stringify(report));
    } catch (error) {
      disposeMcpFnTargetSuiteArtifactGuard(report);
      throw error;
    }
  };
  try {
    const report = await runTargetSuite(options);
    retainArtifactGuard(report);
    return report;
  } catch (error) {
    if (error instanceof McpFnTargetSuiteCleanupError) {
      try {
        retainArtifactGuard(error.report);
      } catch (artifactError) {
        const cause = artifactError instanceof Error
          ? artifactError
          : new Error("Target report artifact proof failed");
        throw new McpFnTargetSuiteArtifactCleanupError(
          () => error.retryCleanup(),
          cause,
        );
      }
    }
    throw error;
  } finally {
    finishRedaction();
  }
}

function beginSuiteArtifactRedaction(target: McpFnTarget): {
  finish: () => void;
  retained: boolean;
} {
  let finish: (() => void) | undefined;
  if (target.beginRedactionScope) {
    try { finish = target.beginRedactionScope(); }
    catch { return { finish: () => undefined, retained: false }; }
    if (!finish) return { finish: () => undefined, retained: false };
  } else {
    finish = beginTargetCredentialRedaction(target);
  }
  return {
    finish: () => {
      try { finish?.(); } catch {}
    },
    retained: true,
  };
}

/** Apply the target-owned scrubber before the bounded generic artifact pass. */
function redactSuiteArtifact<T>(target: McpFnTarget, value: T, options: { preserveKeys?: boolean } = {}): T {
  const scrubbed = target.redact ? target.redact(value, options) : value;
  return redactTargetCredentials(target, scrubbed, options);
}

function compareInventoryNames(left: string, right: string): number {
  if (left === right) return 0;
  return left < right ? -1 : 1;
}

function reportProjectionFailureReason(
  error: unknown,
  projectionFailure: "redaction" | "serialization" | undefined,
): string {
  if (error instanceof McpFnRedactionLimitError) {
    return "Credential redaction exceeded its traversal budget";
  }
  if (projectionFailure === "redaction") {
    return "Credential redaction failed; report content omitted because safe serialization failed";
  }
  return "Report content omitted because safe serialization failed";
}

class SuiteDiagnosticCollector {
  readonly timeline: McpFnDiagnosticEvent[] = [];
  private readonly timelineSizes: number[] = [];
  private timelineBytes = 0;
  private observedRedactionOmissions = 0;
  private initialRedactionOmissions = 0;
  dropped = 0;
  countExceeded = false;
  bytesExceeded = false;
  serializationFailed = false;
  redactionFailed = false;
  cleanupFailure: McpFnReportFailure | undefined;

  constructor(
    private readonly maxEvents: number,
    private readonly maxBytes: number,
    private readonly target: McpFnTarget,
    private readonly consumer?: (event: McpFnDiagnosticEvent) => void | Promise<void>,
  ) {}

  captureBaseline(client: McpFnTestClient): void {
    this.initialRedactionOmissions = client.session
      .getRedactionOmissionCounts().diagnostics;
  }

  captureUnobserved(client: McpFnTestClient | undefined): void {
    const total = client?.session.getRedactionOmissionCounts().diagnostics ??
      this.initialRedactionOmissions;
    const unobserved = Math.max(
      0,
      total - this.initialRedactionOmissions - this.observedRedactionOmissions,
    );
    if (unobserved > 0) {
      this.redactionFailed = true;
      this.dropped += unobserved;
    }
  }

  async record(client: McpFnTestClient | undefined, event: McpFnDiagnosticEvent): Promise<void> {
    if (client?.session.isRedactionOmission(event)) {
      this.observedRedactionOmissions += 1;
      this.redactionFailed = true;
      this.dropped += 1;
    }
    if (["token-revocation", "transport-close"].includes(event.phase) &&
        event.outcome === "failed") {
      this.cleanupFailure ??= normalizeMcpFnReportFailure({
        name: "CleanupError", message: "Target cleanup failed",
        code: event.code, phase: event.phase,
      });
    }
    const safeEvent = redactTargetCredentials(this.target, event, { preserveKeys: true });
    const bytes = this.serializedBytes(safeEvent);
    if (bytes === undefined) {
      await this.consumer?.(safeEvent);
      return;
    }
    if (bytes > this.maxBytes) {
      this.bytesExceeded = true;
      this.dropped += 1;
    } else {
      this.timeline.push(safeEvent);
      this.timelineSizes.push(bytes);
      this.timelineBytes += bytes;
      this.enforceBounds();
    }
    await this.consumer?.(safeEvent);
  }

  private serializedBytes(event: McpFnDiagnosticEvent): number | undefined {
    try {
      const json = JSON.stringify(event, (_key, value: unknown) => {
        if (value === undefined || (typeof value === "number" && !Number.isFinite(value))) {
          throw new Error("Diagnostic contains a non-JSON value");
        }
        return value;
      });
      structuredClone(event);
      return Buffer.byteLength(json);
    } catch {
      this.serializationFailed = true;
      this.dropped += 1;
      return undefined;
    }
  }

  private enforceBounds(): void {
    while (this.timeline.length > this.maxEvents || this.timelineBytes > this.maxBytes) {
      this.countExceeded ||= this.timeline.length > this.maxEvents;
      this.bytesExceeded ||= this.timelineBytes > this.maxBytes;
      this.timeline.shift();
      this.timelineBytes -= this.timelineSizes.shift()!;
      this.dropped += 1;
    }
  }
}

interface SuiteExecution {
  results: McpFnScenarioResult[];
  server?: Implementation;
  capabilities?: ServerCapabilities;
}

interface SuiteProjection {
  target: McpFnTargetDescriptor;
  manifestHash?: string;
  execution: SuiteExecution;
  failure?: "redaction" | "serialization";
}

async function executeConnectedSuite(
  client: McpFnTestClient,
  options: RunMcpFnTargetSuiteOptions,
): Promise<{ execution: SuiteExecution; manifestChecked: boolean }> {
  let manifestChecked = false;
  if (options.manifest) {
    manifestChecked = true;
    await assertManifestContract(client, options.manifest, {
      expectedToolNames: options.expectedToolNames,
    });
  } else if (options.expectedToolNames) {
    const actual = (await client.listTools()).map((tool) => tool.name).sort(compareInventoryNames);
    const expected = [...options.expectedToolNames].sort(compareInventoryNames);
    if (stableJson(actual) !== stableJson(expected)) {
      throw new McpFnAssertionError(
        `Tool inventory mismatch: expected ${stableJson(expected)}, actual ${stableJson(actual)}`,
      );
    }
  }
  const results = await runScenarios(client, options.scenarios ?? [], options.scenarioRun);
  return {
    manifestChecked,
    execution: {
      results,
      server: client.session.getServerVersion(),
      capabilities: client.session.getServerCapabilities(),
    },
  };
}

function safeTargetFailure(target: McpFnTarget, error: unknown): McpFnReportFailure {
  try {
    return normalizeMcpFnReportFailure(redactSuiteArtifact(target, error, { preserveKeys: true }));
  } catch {
    // Arbitrary error properties/proxies can throw, including secret-bearing errors.
    return normalizeMcpFnReportFailure({
      name: "RedactionError",
      code: "MCPFN_REDACTION_FAILED",
      message: "Target failure omitted because credential redaction failed",
    });
  }
}

function initialTargetDescriptor(target: McpFnTarget): McpFnTargetDescriptor {
  const kind = target.kind;
  return ["stdio", "streamable-http", "authenticated-streamable-http", "in-memory", "custom"]
    .includes(kind)
    ? { kind }
    : { kind: "custom" };
}

function safeInitialTargetDescriptor(target: McpFnTarget): McpFnTargetDescriptor {
  try { return initialTargetDescriptor(target); }
  catch { return { kind: "custom" }; }
}

function projectSuiteArtifacts(
  options: RunMcpFnTargetSuiteOptions,
  client: McpFnTestClient | undefined,
  execution: SuiteExecution,
): SuiteProjection {
  const fallback: SuiteProjection = {
    target: safeInitialTargetDescriptor(options.target), execution,
  };
  try {
    if (client?.session.state !== "connected") {
      return execution.results.length || execution.server || execution.capabilities
        ? { ...fallback, failure: "serialization" }
        : fallback;
    }
    let described: McpFnTargetDescriptor;
    try { described = options.target.describe(); }
    catch { return { ...fallback, failure: "serialization" }; }
    try {
      const { kind, ...descriptor } = described;
      return {
        target: {
          ...redactSuiteArtifact(options.target, descriptor, { preserveKeys: false }),
          kind: client.session.preserveArtifactStructure(kind),
        },
        manifestHash: options.manifest
          ? redactSuiteArtifact(options.target, options.manifest.hash, { preserveKeys: false })
          : undefined,
        execution: {
          server: execution.server === undefined
            ? undefined
            : redactSuiteArtifact(options.target, execution.server, { preserveKeys: false }),
          capabilities: execution.capabilities === undefined
            ? undefined
            : redactSuiteArtifact(options.target, execution.capabilities, { preserveKeys: false }),
          results: execution.results.map(result => ({
            ...result,
            name: redactSuiteArtifact(options.target, result.name, { preserveKeys: false }),
            operation: redactSuiteArtifact(options.target, result.operation, { preserveKeys: false }),
            ...(result.tool === undefined ? {} : {
              tool: redactSuiteArtifact(options.target, result.tool, { preserveKeys: false }),
            }),
          })),
        },
      };
    } catch {
      return { ...fallback, failure: "redaction" };
    }
  } catch {
    return { ...fallback, failure: "serialization" };
  }
}

const suiteStructureKeys = [
  "formatVersion", "kind", "artifactValidation", "status", "runtime", "ok", "target", "server",
  "capabilities", "manifestChecked", "manifestHash", "total", "passed", "failed",
  "incomplete", "droppedResults", "droppedObservedEvents",
  "redactionOmittedObservedEvents", "incompleteReason", "failure", "timeline",
  "droppedTimelineEvents", "results", "node", "scenarioFormatVersion",
  "reportSchemaVersion", "packages", "testing", "name", "message", "layer", "code",
  "phase", "details", "outcome", "requestId", "at", "sideEffect", "durationMs",
  "error", "operation", "tool",
] as const;

const suiteStructureValues = [
  "mcpfn.target-suite-report", "target-aware", "complete", "incomplete", "passed", "failed",
  "started", "succeeded", "none", "idempotent", "non-idempotent",
  "mcpfn-preflight", "authorization-server", "resource-server", "mcp-initialization",
  "scenario", "upstream-conformance", "resource-discovery",
  "authorization-server-discovery", "client-registration", "authorization-request",
  "authorization-callback", "token-exchange", "token-refresh", "token-revocation",
  "transport-connect", "mcp-initialize", "capability-operation", "transport-close",
  "authenticated-streamable-http", "streamable-http", "stdio", "in-memory", "custom",
] as const;

interface SuiteStructureGuard {
  assert(value: string): void;
}

function captureSuiteStructureGuard(
  target: McpFnTarget,
  projection: SuiteProjection,
  diagnostics: SuiteDiagnosticCollector,
  failure: McpFnReportFailure | undefined,
): SuiteStructureGuard {
  const candidates = new Set<string>([
    ...suiteStructureKeys,
    ...suiteStructureValues,
    process.version,
    MCPFN_REPORT_SCHEMA_VERSION,
    MCPFN_TESTING_VERSION,
    projection.target.kind,
  ]);
  if (failure?.phase) candidates.add(failure.phase);
  for (const result of projection.execution.results) {
    candidates.add(result.status);
    if (result.sideEffect) candidates.add(result.sideEffect);
  }
  for (const event of diagnostics.timeline) {
    candidates.add(event.phase);
    candidates.add(event.outcome);
    if (event.target?.kind) candidates.add(event.target.kind);
  }
  const safe = new Set<string>();
  for (const candidate of candidates) {
    try {
      if (redactSuiteArtifact(target, candidate, { preserveKeys: false }) === candidate) {
        safe.add(candidate);
      }
    } catch {
      // If the live custom scrubber cannot classify a string, fail closed only
      // when the final report actually needs that unproven structure.
    }
  }
  return {
    assert(value: string): void {
      if (!safe.has(value)) throw new McpFnStructuralCredentialCollisionError();
    },
  };
}

function assertStructureKeys(value: object, guard: SuiteStructureGuard): void {
  for (const key of Object.keys(value)) guard.assert(key);
}

function assertTargetStructure(
  target: McpFnTargetDescriptor,
  guard: SuiteStructureGuard,
): void {
  guard.assert("kind");
  guard.assert(target.kind);
}

function assertSuiteReportStructure(
  report: McpFnTargetSuiteReport,
  guard: SuiteStructureGuard,
): void {
  assertStructureKeys(report, guard);
  guard.assert(report.kind);
  if (report.artifactValidation) guard.assert(report.artifactValidation);
  guard.assert(report.status);
  assertStructureKeys(report.runtime, guard);
  guard.assert(report.runtime.node);
  guard.assert(report.runtime.reportSchemaVersion);
  assertStructureKeys(report.runtime.packages, guard);
  guard.assert(report.runtime.packages.testing);
  assertTargetStructure(report.target, guard);
  if (report.failure) {
    assertStructureKeys(report.failure, guard);
    guard.assert(report.failure.layer);
    if (report.failure.phase) guard.assert(report.failure.phase);
  }
  for (const event of report.timeline) {
    assertStructureKeys(event, guard);
    guard.assert(event.phase);
    guard.assert(event.outcome);
    if (event.target) assertTargetStructure(event.target, guard);
  }
  for (const result of report.results) {
    assertStructureKeys(result, guard);
    guard.assert(result.status);
    if (result.sideEffect) guard.assert(result.sideEffect);
  }
}

async function closeSuiteClient(client: McpFnTestClient | undefined): Promise<{
  cleanupFailure?: McpFnReportFailure;
  retainedCleanup?: () => Promise<void>;
}> {
  try {
    await client?.close();
    return {};
  } catch (error) {
    let retainedCleanup: (() => Promise<void>) | undefined;
    if (error instanceof McpFnTestClientCleanupError) {
      retainedCleanup = () => error.retryCleanup();
    } else if (client) {
      retainedCleanup = () => client.close();
    }
    const terminal = error instanceof McpFnTestClientCleanupError && error.cause !== undefined
      ? error.cause
      : error;
    const phase = terminal && typeof terminal === "object" &&
        (terminal as { phase?: unknown }).phase === "token-revocation"
      ? "token-revocation"
      : "transport-close";
    return {
      retainedCleanup,
      cleanupFailure: normalizeMcpFnReportFailure({
        name: "CleanupError",
        message: "Target cleanup failed",
        code: "MCPFN_TARGET_CLEANUP_FAILED",
        phase,
      }),
    };
  }
}

interface SuiteConnection {
  client?: McpFnTestClient;
  initialClientEventRedactionOmissions: number;
  manifestChecked: boolean;
  failure?: McpFnReportFailure;
  execution: SuiteExecution;
}

async function connectSuite(
  options: RunMcpFnTargetSuiteOptions,
  diagnostics: SuiteDiagnosticCollector,
): Promise<SuiteConnection> {
  let client: McpFnTestClient | undefined;
  let initialClientEventRedactionOmissions = 0;
  let manifestChecked = false;
  let failure: McpFnReportFailure | undefined;
  let execution: SuiteExecution = { results: [] };
  try {
    client = McpFnTestClient.createTarget(
      options.target,
      options.clientInfo ?? { name: "mcpfn-suite", version: "0.0.1" },
      {
        ...options.client,
        diagnostics: event => diagnostics.record(client, event),
      },
    );
    initialClientEventRedactionOmissions = client.session
      .getRedactionOmissionCounts().clientEvents;
    diagnostics.captureBaseline(client);
    await client.session.connect();
    ({ execution, manifestChecked } = await executeConnectedSuite(client, options));
  } catch (error) {
    failure = safeTargetFailure(options.target, error);
  }
  return {
    client,
    initialClientEventRedactionOmissions,
    manifestChecked,
    failure,
    execution,
  };
}

async function projectAndCloseSuite(
  options: RunMcpFnTargetSuiteOptions,
  diagnostics: SuiteDiagnosticCollector,
  connection: SuiteConnection,
): Promise<{
  projection: SuiteProjection;
  structureGuard: SuiteStructureGuard;
  closeResult: Awaited<ReturnType<typeof closeSuiteClient>>;
}> {
  let projection: SuiteProjection;
  let structureGuard: SuiteStructureGuard;
  let closeResult: Awaited<ReturnType<typeof closeSuiteClient>> = {};
  try {
    projection = projectSuiteArtifacts(options, connection.client, connection.execution);
    structureGuard = captureSuiteStructureGuard(
      options.target,
      projection,
      diagnostics,
      connection.failure,
    );
  } finally {
    closeResult = await closeSuiteClient(connection.client);
  }
  return { projection, structureGuard, closeResult };
}

function suiteIncompleteReasons(
  failure: McpFnReportFailure | undefined,
  cleanupFailure: McpFnReportFailure | undefined,
  diagnostics: SuiteDiagnosticCollector,
  redactionOmittedObservedEvents: number,
  overflowedObservedEvents: number,
): string | undefined {
  const reasons = [
    ...(failure ? [`${failure.layer}: ${failure.message}`] : []),
    ...(cleanupFailure ? [`Cleanup: ${cleanupFailure.message}`] : []),
    ...(diagnostics.serializationFailed ? ["Diagnostic timeline contained non-JSON data"] : []),
    ...(diagnostics.redactionFailed ? ["Diagnostic timeline redaction failed; original events omitted"] : []),
    ...(diagnostics.countExceeded ? ["Diagnostic timeline exceeded maxTimelineEvents"] : []),
    ...(diagnostics.bytesExceeded ? ["Diagnostic timeline exceeded maxReportBytes"] : []),
    ...(redactionOmittedObservedEvents > 0
      ? ["Observed client events were omitted because credential redaction failed"]
      : []),
    ...(overflowedObservedEvents > 0
      ? ["Observed client events exceeded maxObservedEvents"]
      : []),
  ];
  return reasons.length ? reasons.join("; ") : undefined;
}

function buildSuiteReport(
  projection: SuiteProjection,
  manifestChecked: boolean,
  failure: McpFnReportFailure | undefined,
  cleanupFailure: McpFnReportFailure | undefined,
  diagnostics: SuiteDiagnosticCollector,
  lifecycleRedactionOmissions: number,
): McpFnTargetSuiteReport {
  const results = projection.execution.results;
  const failed = results.filter((result) => result.status === "failed").length;
  const incomplete = results.filter((result) => result.status === "incomplete").length;
  const scenarioDroppedObservedEvents = results.reduce(
    (total, result) => total + (result.droppedObservedEvents ?? 0),
    0,
  );
  const scenarioRedactionOmissions = results.reduce(
    (total, result) => total + (result.redactionOmittedObservedEvents ?? 0),
    0,
  );
  const redactionOmittedObservedEvents = Math.max(
    lifecycleRedactionOmissions,
    scenarioRedactionOmissions,
  );
  const overflowedObservedEvents = Math.max(
    0,
    scenarioDroppedObservedEvents - scenarioRedactionOmissions,
  );
  const droppedObservedEvents = redactionOmittedObservedEvents + overflowedObservedEvents;
  const artifactIncomplete = Boolean(failure) || incomplete > 0 ||
    diagnostics.dropped > 0 || droppedObservedEvents > 0;
  const incompleteReason = suiteIncompleteReasons(
    failure,
    cleanupFailure,
    diagnostics,
    redactionOmittedObservedEvents,
    overflowedObservedEvents,
  );
  return {
    formatVersion: 1,
    kind: "mcpfn.target-suite-report",
    artifactValidation: "target-aware",
    status: artifactIncomplete ? "incomplete" : "complete",
    runtime: {
      node: process.version,
      scenarioFormatVersion: 1,
      reportSchemaVersion: MCPFN_REPORT_SCHEMA_VERSION,
      packages: { testing: MCPFN_TESTING_VERSION },
    },
    ok: failed === 0 && !artifactIncomplete,
    target: projection.target,
    server: projection.execution.server,
    capabilities: projection.execution.capabilities,
    manifestChecked,
    ...(projection.manifestHash === undefined ? {} : { manifestHash: projection.manifestHash }),
    total: results.length,
    passed: results.length - failed - incomplete,
    failed,
    incomplete,
    droppedResults: 0,
    droppedObservedEvents,
    ...(redactionOmittedObservedEvents > 0 ? { redactionOmittedObservedEvents } : {}),
    ...(incompleteReason ? { incompleteReason } : {}),
    ...(failure ? { failure } : {}),
    timeline: diagnostics.timeline,
    droppedTimelineEvents: diagnostics.dropped,
    results,
  };
}

function structuralReportFailure(retainedCleanup: (() => Promise<void>) | undefined): never {
  const failure = new McpFnClientError(
    "MCPFN_OPERATION_FAILED",
    "Target report cannot be serialized because a credential conflicts with required artifact structure",
    { phase: "capability-operation" },
  );
  if (retainedCleanup) {
    throw new McpFnTargetSuiteArtifactCleanupError(retainedCleanup, failure);
  }
  throw failure;
}

function boundedSuiteReport(
  report: McpFnTargetSuiteReport,
  guard: SuiteStructureGuard,
  maxReportBytes: number,
): McpFnTargetSuiteReport {
  const bounded = enforceReportCap(report, maxReportBytes);
  assertSuiteReportStructure(bounded, guard);
  return bounded;
}

function finalizeSuiteReport(
  options: RunMcpFnTargetSuiteOptions,
  projection: SuiteProjection,
  report: McpFnTargetSuiteReport,
  guard: SuiteStructureGuard,
  maxReportBytes: number,
  retainedCleanup: (() => Promise<void>) | undefined,
): McpFnTargetSuiteReport {
  let finalized: McpFnTargetSuiteReport;
  try {
    if (projection.failure) throw new Error("Report payload projection failed");
    assertSuiteReportStructure(report, guard);
    // Custom redaction already completed before cleanup. Built-in report scopes
    // remain active here for bounded final serialization.
    finalized = boundedSuiteReport(
      redactTargetCredentials(options.target, report, { preserveKeys: true }),
      guard,
      maxReportBytes,
    );
  } catch (error) {
    if (error instanceof McpFnStructuralCredentialCollisionError) {
      return structuralReportFailure(retainedCleanup);
    }
    const fallback = {
      ...report,
      ok: false,
      status: "incomplete" as const,
      incompleteReason: reportProjectionFailureReason(error, projection.failure),
      target: { kind: "custom" as const },
      server: undefined,
      capabilities: undefined,
      manifestHash: undefined,
      failure: undefined,
      results: [],
      timeline: [],
      droppedResults: report.results.length,
      droppedTimelineEvents: report.droppedTimelineEvents + report.timeline.length,
    };
    try {
      finalized = boundedSuiteReport(
        redactTargetCredentials(options.target, fallback, { preserveKeys: true }),
        guard,
        maxReportBytes,
      );
    } catch (fallbackError) {
      if (fallbackError instanceof McpFnRedactionLimitError) {
        return structuralReportFailure(retainedCleanup);
      }
      throw fallbackError;
    }
  }
  if (retainedCleanup) throw new McpFnTargetSuiteCleanupError(finalized, retainedCleanup);
  return finalized;
}

async function runTargetSuite(options: RunMcpFnTargetSuiteOptions): Promise<McpFnTargetSuiteReport> {
  const maxTimelineEvents = options.maxTimelineEvents ?? 500;
  if (!Number.isInteger(maxTimelineEvents) || maxTimelineEvents < 1) {
    throw new Error("maxTimelineEvents must be a positive integer");
  }
  const maxReportBytes = options.maxReportBytes ?? 1_048_576;
  validateReportCap(maxReportBytes);
  const consumerDiagnostic = options.client?.diagnostics;
  const diagnostics = new SuiteDiagnosticCollector(
    maxTimelineEvents,
    maxReportBytes,
    options.target,
    consumerDiagnostic,
  );
  const connection = await connectSuite(options, diagnostics);
  // Custom hooks may depend on credentials cleared by close. Capture payload
  // projection and structural safety while the session still owns that state,
  // but never let either operation bypass the sole cleanup boundary.
  const { projection, structureGuard, closeResult } = await projectAndCloseSuite(
    options,
    diagnostics,
    connection,
  );
  const { cleanupFailure: closeFailure, retainedCleanup } = closeResult;
  diagnostics.captureUnobserved(connection.client);
  const lifecycleRedactionOmissions = Math.max(
    0,
    (connection.client?.session.getRedactionOmissionCounts().clientEvents ??
      connection.initialClientEventRedactionOmissions) -
      connection.initialClientEventRedactionOmissions,
  );
  let cleanupFailure = closeFailure;
  cleanupFailure ??= diagnostics.cleanupFailure;
  const failure = connection.failure ?? cleanupFailure;
  const report = buildSuiteReport(
    projection,
    connection.manifestChecked,
    failure,
    cleanupFailure,
    diagnostics,
    lifecycleRedactionOmissions,
  );
  return finalizeSuiteReport(
    options,
    projection,
    report,
    structureGuard,
    maxReportBytes,
    retainedCleanup,
  );
}

function enforceReportCap(
  report: McpFnTargetSuiteReport,
  maxBytes: number,
): McpFnTargetSuiteReport {
  validateReportCap(maxBytes);
  const bounded = structuredClone(report);
  if (jsonBytes(bounded) > maxBytes) {
    bounded.ok = false;
    bounded.status = "incomplete";
    bounded.incompleteReason = "Report content exceeded maxReportBytes and was truncated";
  }
  while (jsonBytes(bounded) > maxBytes && bounded.results.length > 0) {
    bounded.results.pop();
    bounded.droppedResults += 1;
  }
  if (jsonBytes(bounded) > maxBytes) {
    bounded.target = { kind: report.target.kind };
    bounded.server = undefined;
    bounded.capabilities = undefined;
    bounded.timeline = [];
    bounded.droppedTimelineEvents += report.timeline.length;
    if (bounded.failure) {
      bounded.failure.details = undefined;
      bounded.failure.message = "Target operation failed; details omitted to fit report budget";
    }
  }
  if (bounded.droppedResults > 0 || jsonBytes(bounded) > maxBytes) {
    bounded.ok = false;
    bounded.status = "incomplete";
    bounded.incompleteReason = "Report content exceeded maxReportBytes and was truncated";
  }
  if (jsonBytes(bounded) > maxBytes) {
    throw new Error("The minimum target suite report exceeds maxReportBytes");
  }
  return bounded;
}

function validateReportCap(maxBytes: number): void {
  if (!Number.isInteger(maxBytes) || maxBytes < 1_024) {
    throw new Error("maxReportBytes must be an integer of at least 1024");
  }
}

function jsonBytes(value: unknown): number {
  return new TextEncoder().encode(JSON.stringify(value)).byteLength;
}
