      .filter(([, entry]) => entry !== undefined)
      .sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0)
      .map(([key, entry]) => `${JSON.stringify(key)}:${stableJson(entry)}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

export class McpFnAssertionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "McpFnAssertionError";
  }
}

export interface AssertManifestContractOptions {
  /** Exact tools expected to be visible for the test client's request context. */
  expectedToolNames?: readonly string[];
}

export async function assertManifestContract(
  client: McpFnTestClient<unknown>,
  manifest: McpFnManifest,
  options: AssertManifestContractOptions = {},
): Promise<Tool[]> {
  const actual = await client.listTools();
  const actualByName = new Map(actual.map((tool) => [tool.name, tool]));
  const manifestByName = new Map(manifest.tools.map((tool) => [tool.name, tool]));
  const expectedNames = [...(
    options.expectedToolNames ?? manifest.tools.map((tool) => tool.name)
  )].sort();
  const unknownExpectedNames = expectedNames.filter((name) => !manifestByName.has(name));
  if (unknownExpectedNames.length) {
    throw new McpFnAssertionError(
      `Expected visible tools are absent from the manifest: ${stableJson(unknownExpectedNames)}`,
    );
  }
  const actualNames = actual.map((tool) => tool.name).sort();
  if (stableJson(expectedNames) !== stableJson(actualNames)) {
    throw new McpFnAssertionError(
      `Tool inventory mismatch\nexpected: ${stableJson(expectedNames)}\nactual:   ${stableJson(actualNames)}`,
    );
  }
  for (const name of expectedNames) {
    const expected = manifestByName.get(name)!;
    const tool = actualByName.get(expected.name)!;
    const comparableExpected = {
      name: expected.name,
      description: expected.description,
      inputSchema: expected.inputSchema,
      outputSchema: expected.outputSchema,
      annotations: expected.annotations,
      execution: expected.execution,
      icons: expected.icons,
      title: expected.title,
      _meta: expected.metadata,
    };
    const comparableActual = {
      name: tool.name,
      description: tool.description,
      inputSchema: tool.inputSchema,
      outputSchema: tool.outputSchema,
      annotations: tool.annotations,
      execution: tool.execution,
      icons: tool.icons,
      title: tool.title,
      _meta: tool._meta,
    };
    if (stableJson(comparableExpected) !== stableJson(comparableActual)) {
      throw new McpFnAssertionError(
        `Contract mismatch for ${expected.name}\nexpected: ${stableJson(comparableExpected)}\nactual:   ${stableJson(comparableActual)}`,
      );
    }
  }

  const actualCapabilities = client.client.getServerCapabilities() ?? {};
  if (stableJson(manifest.capabilities ?? {}) !== stableJson(actualCapabilities)) {
    throw new McpFnAssertionError(
      `Capability mismatch\nexpected: ${stableJson(manifest.capabilities ?? {})}\nactual:   ${stableJson(actualCapabilities)}`,
    );
  }

  const actualResources = actualCapabilities.resources
    ? await client.listResources()
    : [];
  const comparableResources = actualResources.map(({ _meta, ...resource }) => ({
    ...resource,
    metadata: _meta,
  }));
  const staticResourceUris = new Set(
    (manifest.resources ?? []).map((resource) => resource.uri),
  );
  const resourceTemplates = (manifest.resourceTemplates ?? []).map(
    (template) => new UriTemplate(template.uriTemplate),
  );
  const comparableStaticResources = comparableResources.filter(
    (resource) =>
      staticResourceUris.has(resource.uri) ||
      !resourceTemplates.some((template) => template.match(resource.uri)),
  );
  const expectedResources = (manifest.resources ?? []).map(
    ({ subscribable: _subscribable, ...resource }) => resource,
  );
  if (stableJson(expectedResources) !== stableJson(comparableStaticResources)) {
    throw new McpFnAssertionError(
      `Resource inventory mismatch\nexpected: ${stableJson(expectedResources)}\nactual:   ${stableJson(comparableStaticResources)}`,
    );
  }

  const actualTemplates = actualCapabilities.resources
    ? await client.listResourceTemplates()
    : [];
  const comparableTemplates = actualTemplates.map(({ _meta, ...template }) => ({
    ...template,
    metadata: _meta,
  }));
  const expectedTemplates = (manifest.resourceTemplates ?? []).map(
    ({ subscribable: _subscribable, ...template }) => template,
  );
  if (stableJson(expectedTemplates) !== stableJson(comparableTemplates)) {
    throw new McpFnAssertionError(
      `Resource template inventory mismatch\nexpected: ${stableJson(expectedTemplates)}\nactual:   ${stableJson(comparableTemplates)}`,
    );
  }

  for (const resource of comparableResources) {
    const expected = (manifest.resources ?? []).find(
      (candidate) => candidate.uri === resource.uri,
    ) ?? (manifest.resourceTemplates ?? []).find(
      (candidate) => new UriTemplate(candidate.uriTemplate).match(resource.uri),
    );
    const subscribable = expected?.subscribable === true;
    if (subscribable) {
      try {
        await client.subscribeResource(resource.uri);
        await client.unsubscribeResource(resource.uri);
      } catch (error) {
        throw new McpFnAssertionError(
          `Resource subscription mismatch for ${resource.uri}: expected subscribe and unsubscribe to succeed (${error instanceof Error ? error.message : String(error)})`,
        );
      }
      continue;
    }
    let accepted = false;
    try {
      await client.subscribeResource(resource.uri);
      accepted = true;
      await client.unsubscribeResource(resource.uri).catch(() => undefined);
    } catch {
      // Rejection is the expected behavior for a non-subscribable resource.
    }
    if (accepted) {
      throw new McpFnAssertionError(
        `Resource subscription mismatch for ${resource.uri}: expected subscribe to be rejected`,
      );
    }
  }

  const actualPrompts = actualCapabilities.prompts
    ? await client.listPrompts()
    : [];
  const comparablePrompts = actualPrompts.map(({ _meta, ...prompt }) => ({
    ...prompt,
    metadata: _meta,
  }));
  const expectedPrompts = (manifest.prompts ?? []).map(({ argumentsSchema: _schema, ...prompt }) => prompt);
  if (stableJson(expectedPrompts) !== stableJson(comparablePrompts)) {
    throw new McpFnAssertionError(
      `Prompt inventory mismatch\nexpected: ${stableJson(expectedPrompts)}\nactual:   ${stableJson(comparablePrompts)}`,
    );
  }
  return actual;
}

export function assertStructuredTextParity(result: {
  content?: unknown[];
  structuredContent?: Record<string, unknown>;
}): void {
  if (!result.structuredContent) {
    throw new McpFnAssertionError("Tool result has no structuredContent");
  }
  const text = (result.content ?? []).find(
    (entry): entry is { type: "text"; text: string } =>
      !!entry &&
      typeof entry === "object" &&
      (entry as { type?: unknown }).type === "text" &&
      typeof (entry as { text?: unknown }).text === "string",
  )?.text;
  if (!text) {
    throw new McpFnAssertionError("Tool result has no text content");
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new McpFnAssertionError("Tool text content is not JSON");
  }
  if (stableJson(parsed) !== stableJson(result.structuredContent)) {
    throw new McpFnAssertionError(
      "Tool text content and structuredContent are not equivalent",
    );
  }
}
","export type McpFnAuthCredentialKind = "api-key" | "oauth";

export interface McpFnAuthCredential {
  kind: McpFnAuthCredentialKind;
  headers: HeadersInit;
  label?: string;
  dispose?(): void | Promise<void>;
}

export interface McpFnAuthCredentialRequest {
  kind: McpFnAuthCredentialKind;
  scopes?: string[];
  resource?: string;
  expiresInSeconds?: number;
}

export interface McpFnAuthProviderCapabilities {
  expiration?: boolean;
  resourceBinding?: boolean;
  revocation?: boolean;
  scopes?: boolean;
}

/**
 * The application-owned seam. Skillplane only needs to map this interface to
 * its existing API-key or OAuth issuance and revocation helpers.
 */
export interface McpFnAuthProviderAdapter {
  capabilities?: McpFnAuthProviderCapabilities;
  issue(input: McpFnAuthCredentialRequest): Promise<McpFnAuthCredential>;
  revoke?(credential: McpFnAuthCredential): void | Promise<void>;
}

export interface McpFnAuthProbeScenario {
  name:
    | "missing-credential"
    | "invalid-credential"
    | "valid-credential"
    | "insufficient-scope"
    | "expired-credential"
    | "missing-resource"
    | "wrong-resource"
    | "revoked-credential";
  kind: McpFnAuthCredentialKind;
}

export interface McpFnAuthTarget {
  request(
    headers: Headers,
    scenario: McpFnAuthProbeScenario,
  ): Promise<Response>;
}

export interface McpFnAuthRegressionOptions {
  kind: McpFnAuthCredentialKind;
  provider: McpFnAuthProviderAdapter;
  target: McpFnAuthTarget;
  requiredScopes?: string[];
  resource?: string;
  wrongResource?: string;
  invalidCredentialHeaders?: HeadersInit;
  /** OAuth failures are required to advertise protected-resource metadata. */
  protectedResourceMetadataUrl?: string;
  expectedAuthenticatedStatuses?: number[];
  verifyAuthenticatedResponse?(
    response: Response,
    credential: McpFnAuthCredential,
  ): void | Promise<void>;
}

export interface McpFnAuthScenarioResult {
  name: McpFnAuthProbeScenario["name"];
  status: "passed" | "failed";
  responseStatus?: number;
  error?: string;
}

export interface McpFnBearerChallenge {
  scheme: string;
  parameters: Record<string, string>;
}

export class McpFnAuthAssertionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "McpFnAuthAssertionError";
  }
}

function expectedStatus(
  response: Response,
  expected: number | number[],
  name: string,
): void {
  const statuses = Array.isArray(expected) ? expected : [expected];
  if (!statuses.includes(response.status)) {
    throw new McpFnAuthAssertionError(
      `${name} expected HTTP ${statuses.join(" or ")}, received ${response.status}`,
    );
  }
}

export function parseBearerChallenge(
  header: string | null,
): McpFnBearerChallenge | undefined {
  if (!header) return undefined;
  const matches = [...header.matchAll(/(?:^|,)\s*([A-Za-z][A-Za-z0-9_-]*)\s+/g)];
  const selectedIndex = matches.findIndex((entry) => entry[1].toLowerCase() === "bearer");
  if (selectedIndex < 0) return undefined;
  const match = matches[selectedIndex];
  const start = (match.index ?? 0) + match[0].length;
  const end = matches[selectedIndex + 1]?.index ?? header.length;
  const parameters: Record<string, string> = {};
  const source = header.slice(start, end);
  const pattern = /([A-Za-z][A-Za-z0-9_-]*)\s*=\s*(?:"((?:[^"\\]|\\.)*)"|([^,\s]+))/g;
  for (const entry of source.matchAll(pattern)) {
    const quoted = entry[2]?.replace(/\\(["\\])/g, "$1");
    parameters[entry[1]] = quoted ?? entry[3] ?? "";
  }
  return { scheme: match[1], parameters };
}

export function assertBearerResourceChallenge(
  response: Response,
  expectedMetadataUrl?: string,
): McpFnBearerChallenge {
  const challenge = parseBearerChallenge(response.headers.get("www-authenticate"));
  if (!challenge || challenge.scheme.toLowerCase() !== "bearer") {
    throw new McpFnAuthAssertionError("Expected a Bearer WWW-Authenticate challenge");
  }
  const metadataUrl = challenge.parameters.resource_metadata;
  if (!metadataUrl) {
    throw new McpFnAuthAssertionError(
      "Bearer challenge is missing the resource_metadata parameter",
    );
  }
  try {
    const parsed = new URL(metadataUrl);
    if (!parsed.protocol || !parsed.host) throw new Error("not absolute");
  } catch {
    throw new McpFnAuthAssertionError(
      `Bearer challenge has an invalid resource_metadata URL: ${metadataUrl}`,
    );
  }
  if (expectedMetadataUrl && metadataUrl !== expectedMetadataUrl) {
    throw new McpFnAuthAssertionError(
      `Expected resource_metadata=${expectedMetadataUrl}, received ${metadataUrl}`,
    );
  }
  return challenge;
}

export function bearerCredential(
  token: string,
  kind: McpFnAuthCredentialKind = "oauth",
): McpFnAuthCredential {
  return {
    kind,
    headers: { authorization: `Bearer ${token}` },
  };
}

export function apiKeyCredential(
  apiKey: string,
  options: { headerName?: string; scheme?: string } = {},
): McpFnAuthCredential {
  const headerName = options.headerName ?? "authorization";
  const value = options.scheme === ""
    ? apiKey
    : `${options.scheme ?? "Bearer"} ${apiKey}`;
  return { kind: "api-key", headers: { [headerName]: value } };
}

function invalidHeaders(options: McpFnAuthRegressionOptions): Headers {
  return new Headers(options.invalidCredentialHeaders ?? {
    authorization: `Bearer mcpfn-invalid-${options.kind}`,
  });
}

async function runOne(
  options: McpFnAuthRegressionOptions,
  scenario: McpFnAuthProbeScenario,
  prepare: () => Promise<McpFnAuthCredential | undefined>,
  expected: number | number[],
): Promise<McpFnAuthScenarioResult> {
  let credential: McpFnAuthCredential | undefined;
  try {
    credential = await prepare();
    const headers = credential
      ? new Headers(credential.headers)
      : scenario.name === "invalid-credential"
        ? invalidHeaders(options)
        : new Headers();
    const response = await options.target.request(headers, scenario);
    expectedStatus(response, expected, scenario.name);
    if (
      options.kind === "oauth" &&
      scenario.name !== "valid-credential"
    ) {
      assertBearerResourceChallenge(
        response,
        options.protectedResourceMetadataUrl,
      );
    }
    if (scenario.name === "valid-credential" && credential) {
      await options.verifyAuthenticatedResponse?.(response.clone(), credential);
    }
    return {
      name: scenario.name,
      status: "passed",
      responseStatus: response.status,
    };
  } catch (error) {
    return {
      name: scenario.name,
      status: "failed",
      error: error instanceof Error ? error.message : String(error),
    };
  } finally {
    await credential?.dispose?.();
  }
}

/** Runs the common API-key or OAuth resource-server regression matrix. */
export async function runAuthRegressionSuite(
  options: McpFnAuthRegressionOptions,
): Promise<McpFnAuthScenarioResult[]> {
  const issue = (overrides: Partial<McpFnAuthCredentialRequest> = {}) =>
    options.provider.issue({
      kind: options.kind,
      scopes: options.requiredScopes,
      resource: options.resource,
      ...overrides,
    });
  const results: McpFnAuthScenarioResult[] = [];
  results.push(await runOne(
    options,
    { name: "missing-credential", kind: options.kind },
    async () => undefined,
    401,
  ));
  results.push(await runOne(
    options,
    { name: "invalid-credential", kind: options.kind },
    async () => undefined,
    401,
  ));
  results.push(await runOne(
    options,
    { name: "valid-credential", kind: options.kind },
    () => issue(),
    options.expectedAuthenticatedStatuses ?? [200, 201, 202, 204],
  ));

  const capabilities = options.provider.capabilities ?? {};
  if (capabilities.scopes && options.requiredScopes?.length) {
    results.push(await runOne(
      options,
      { name: "insufficient-scope", kind: options.kind },
      () => issue({ scopes: [] }),
      403,
    ));
  }
  if (capabilities.expiration) {
    results.push(await runOne(
      options,
      { name: "expired-credential", kind: options.kind },
      () => issue({ expiresInSeconds: -60 }),
      401,
    ));
  }
  if (capabilities.resourceBinding && options.resource) {
    results.push(await runOne(
      options,
      { name: "missing-resource", kind: options.kind },
      () => issue({ resource: undefined }),
      401,
    ));
  }
  if (capabilities.resourceBinding && options.wrongResource) {
    results.push(await runOne(
      options,
      { name: "wrong-resource", kind: options.kind },
      () => issue({ resource: options.wrongResource }),
      401,
    ));
  }
  if (capabilities.revocation && options.provider.revoke) {
    results.push(await runOne(
      options,
      { name: "revoked-credential", kind: options.kind },
      async () => {
        const credential = await issue();
        await options.provider.revoke?.(credential);
        return credential;
      },
      401,
    ));
  }
  return results;
}

export async function assertAuthRegressionSuite(
  options: McpFnAuthRegressionOptions,
): Promise<McpFnAuthScenarioResult[]> {
  const results = await runAuthRegressionSuite(options);
  const failures = results.filter((result) => result.status === "failed");
  if (failures.length) {
    throw new McpFnAuthAssertionError(
      failures.map((failure) => `${failure.name}: ${failure.error}`).join("\n"),
    );
  }
  return results;
}

export interface McpFnFetchAuthTargetOptions {
  url: string | URL;
  fetch?: typeof globalThis.fetch;
  requestInit?: RequestInit | ((scenario: McpFnAuthProbeScenario) => RequestInit);
}

/** Creates a protected MCP initialize probe suitable for local or deployed endpoints. */
export function createFetchAuthTarget(
  options: McpFnFetchAuthTargetOptions,
): McpFnAuthTarget {
  const fetchImplementation = options.fetch ?? globalThis.fetch;
  if (!fetchImplementation) {
    throw new Error("A fetch implementation is required");
  }
  return {
    async request(authHeaders, scenario) {
      const configured = typeof options.requestInit === "function"
        ? options.requestInit(scenario)
        : options.requestInit ?? {};
      const headers = new Headers(configured.headers);
      headers.set("accept", "application/json, text/event-stream");
      headers.set("content-type", "application/json");
      authHeaders.forEach((value, name) => headers.set(name, value));
      return fetchImplementation(options.url, {
        method: "POST",
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: `mcpfn-auth-${scenario.name}`,
          method: "initialize",
          params: {
            protocolVersion: "2025-11-25",
            capabilities: {},
            clientInfo: { name: "mcpfn-auth-test", version: "1.0.0" },
          },
        }),
        ...configured,
        headers,
      });
    },
  };
}

