export interface McpFnTestClientOptions {
  capabilities?: ClientCapabilities;
  handlers?: McpFnClientMediatedHandlers;
  events?: McpFnClientEventSink;
  /** Install roots, sampling, elicitation, or notification handlers before initialize. */
  configure?(client: Client): void | Promise<void>;
  diagnostics?: McpFnDiagnosticSink;
}

const testClientCleanupOwners = new WeakMap<
  McpFnTestClientCleanupError,
  { close: () => Promise<void>; pending?: Promise<void> }
>();

/** Test-client cleanup failed and remains owned by this retryable error. */
export class McpFnTestClientCleanupError extends Error {
  constructor(close: () => Promise<void>, cause: unknown) {
    super(
      "Test client cleanup remains pending; retain this error and retryCleanup()",
      { cause },
    );
    this.name = "McpFnTestClientCleanupError";
    testClientCleanupOwners.set(this, { close });
  }

  retryCleanup(): Promise<void> {
    const owner = testClientCleanupOwners.get(this);
    if (!owner) return Promise.resolve();
    if (owner.pending) return owner.pending;
    const pending = Promise.resolve().then(owner.close).then(
      () => { testClientCleanupOwners.delete(this); },
      () => { throw this; },
    ).finally(() => { owner.pending = undefined; });
    owner.pending = pending;
    return pending;
  }
}

export class McpFnTestClient<TContext = undefined> {
  readonly session: McpFnClient;

  private constructor(session: McpFnClient) {
    this.session = session;
  }

  get client(): Client {
    return this.session.protocol;
  }

  static async connect<TContext>(
    server: McpFnServer<TContext>,
    info = { name: "mcpfn-test-client", version: "1.0.0" },
    options: McpFnTestClientOptions = {},
  ): Promise<McpFnTestClient<TContext>> {
    const serverName = (server as McpFnServer<TContext> & { info?: { name?: string } })
      .info?.name ?? "mcpfn-server";
    return this.connectTarget<TContext>(customTarget({
      kind: "in-memory",
      descriptor: { server: serverName },
      open: async () => {
        const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
        await server.connect(serverTransport);
        return { transport: clientTransport, close: () => server.close() };
      },
    }), info, options);
  }

  /** Create the session owner before connecting, so failed initialization remains closeable. */
  static createTarget<TContext = undefined>(
    target: McpFnTarget,
    info?: Implementation,
    options: McpFnTestClientOptions = {},
  ): McpFnTestClient<TContext> {
    return new McpFnTestClient<TContext>(createMcpFnClient({
      target,
      info: info ?? { name: "mcpfn-test-client", version: "1.0.0" },
      capabilities: options.capabilities,
      handlers: options.handlers,
      events: options.events,
      configure: options.configure,
      diagnostics: options.diagnostics,
    }));
  }

  static async connectTarget<TContext = undefined>(
    target: McpFnTarget,
    info?: Implementation,
    options: McpFnTestClientOptions = {},
  ): Promise<McpFnTestClient<TContext>> {
    const client = this.createTarget<TContext>(target, info, options);
    try {
      await client.session.connect();
      return client;
    } catch (error) {
      const connectionFailure = error instanceof Error && error.cause !== undefined
        ? error.cause
        : error;
      try { await client.session.close(); }
      catch { throw new McpFnTestClientCleanupError(() => client.session.close(), connectionFailure); }
      throw error;
    }
  }

  listTools(options?: RequestOptions): Promise<Tool[]> { return this.session.tools.listAll(options); }
  callTool(
    name: string,
    args: Record<string, unknown> = {},
    options?: RequestOptions,
  ): Promise<CallToolResult> {
    return this.session.tools.call(name, args, options);
  }
  createToolTask(
    name: string,
    args: Record<string, unknown> = {},
    task: { ttl?: number } = {},
    options?: RequestOptions,
  ): Promise<CreateTaskResult> {
    return this.session.tools.createTask(name, args, task, options);
  }
  getTask(taskId: string, options?: RequestOptions): Promise<Task> {
    return this.session.tasks.get(taskId, options);
  }
  getTaskResult(taskId: string, options?: RequestOptions): Promise<CallToolResult> {
    return this.session.tasks.result(taskId, options);
  }
  listTasks(cursor?: string, options?: RequestOptions): Promise<ListTasksResult> {
    return this.session.tasks.list(cursor, options);
  }
  cancelTask(taskId: string, options?: RequestOptions): Promise<Task> {
    return this.session.tasks.cancel(taskId, options);
  }
  listResources(options?: RequestOptions): Promise<Resource[]> {
    return this.session.resources.listAll(options);
  }
  listResourceTemplates(options?: RequestOptions): Promise<ResourceTemplate[]> {
    return this.session.resources.listTemplatesAll(options);
  }
  readResource(uri: string, options?: RequestOptions): Promise<ReadResourceResult> {
    return this.session.resources.read(uri, options);
  }
  subscribeResource(uri: string, options?: RequestOptions): Promise<void> {
    return this.session.resources.subscribe(uri, options);
  }
  unsubscribeResource(uri: string, options?: RequestOptions): Promise<void> {
    return this.session.resources.unsubscribe(uri, options);
  }
  listPrompts(options?: RequestOptions): Promise<Prompt[]> {
    return this.session.prompts.listAll(options);
  }
  getPrompt(
    name: string,
    args?: Record<string, string>,
    options?: RequestOptions,
  ): Promise<GetPromptResult> {
    return this.session.prompts.get(name, args, options);
  }
  complete(params: CompleteRequest["params"], options?: RequestOptions): Promise<CompleteResult> {
    return this.session.prompts.complete(params, options);
  }
  async close(): Promise<void> {
    try { await this.session.close(); }
    catch (error) {
      throw new McpFnTestClientCleanupError(() => this.session.close(), error);
    }
  }
}
","import { createHash } from "node:crypto";

import Ajv from "ajv";
import Ajv2019 from "ajv/dist/2019.js";
import Ajv2020 from "ajv/dist/2020.js";
import type {
  CallToolResult,
  ClientCapabilities,
  Implementation,
  Tool,
} from "@modelcontextprotocol/sdk/types.js";
import type { McpFnSchemaIssue } from "@mcpfn/core";
import type { McpFnTarget } from "@mcpfn/client";
import { redactOAuthValue } from "@superfunctions/oauth-core";

import { stableJson } from "./assertions.js";
import { McpFnTestClient, McpFnTestClientCleanupError, type McpFnTestClientOptions } from "./client.js";

export type McpFnFixtureSideEffect =
  | "read-only"
  | "idempotent"
  | "non-idempotent";

export interface McpFnClientProfileFixtureExpectation {
  isError?: boolean;
  structuredContent?: Record<string, unknown>;
  errorCode?: string;
  lifecycleStage?: string;
  validationIssue?: Partial<
    Pick<
      McpFnSchemaIssue,
      | "instancePath"
      | "schemaPath"
      | "keyword"
      | "rejectedProperty"
      | "missingProperty"
    >
  >;
}

export interface McpFnClientProfileFixture {
  name: string;
  tool: string;
  /** Values are executed but never copied into compatibility reports. */
  arguments?: Record<string, unknown>;
  sideEffect: McpFnFixtureSideEffect;
  source?: "minimal-valid" | "captured-failure";
  expect?: McpFnClientProfileFixtureExpectation;
}

export interface McpFnSchemaPortabilityPolicy {
  /** Treat otherwise-valid compatibility-reducing keywords as failures. */
  warningsAsErrors?: boolean;
  /** Suppress warnings for explicitly reviewed keywords. */
  allowKeywords?: readonly string[];
}

export interface McpFnSchemaPortabilityIssue {
  severity: "error" | "warning";
  code:
    | "schema-invalid"
    | "schema-dialect-unsupported"
    | "schema-portability-warning";
  path: string;
  keyword?: string;
  message: string;
}

export interface McpFnClientProfileSnapshotTool {
  name: string;
  hash: string;
}

export interface McpFnClientProfileSnapshot {
  formatVersion: 1;
  kind: "mcpfn.client-profile-snapshot";
  profile: { id: string; version: string };
  catalogHash: string;
  tools: McpFnClientProfileSnapshotTool[];
}

export interface McpFnClientProfileSnapshotChange {
  kind: "added" | "removed" | "modified";
  tool: string;
  beforeHash?: string;
  afterHash?: string;
}

export interface McpFnClientProfileSnapshotDiff {
  compatible: boolean;
  changes: McpFnClientProfileSnapshotChange[];
  summary: { added: number; removed: number; modified: number };
}

export interface McpFnClientProfileContractCase {
  id: string;
  version: string;
  target: McpFnTarget;
  clientInfo?: Implementation;
  capabilities?: ClientCapabilities;
  client?: Omit<McpFnTestClientOptions, "capabilities">;
  fixtures?: readonly McpFnClientProfileFixture[];
  expectedSnapshot?: McpFnClientProfileSnapshot;
  portability?: McpFnSchemaPortabilityPolicy;
}

export interface RunMcpFnClientProfileContractsOptions {
  profiles: readonly McpFnClientProfileContractCase[];
  /** Explicit opt-in for fixtures that could mutate state. Defaults to false. */
  allowSideEffects?: boolean;
  /** Aggregate JSON size cap. Defaults to 1 MiB. */
  maxReportBytes?: number;
}

export interface McpFnClientProfileFixtureResult {
  name: string;
  tool: string;
  source: "minimal-valid" | "captured-failure";
  status: "passed" | "failed" | "incomplete";
  code?: string;
  error?: string;
}

export interface McpFnClientProfileContractResult {
  profile: { id: string; version: string };
  status: "complete" | "incomplete";
  ok: boolean;
  phase?: "connect" | "catalog" | "fixtures" | "close";
  snapshot?: McpFnClientProfileSnapshot;
  snapshotMatches?: boolean;
  portability: McpFnSchemaPortabilityIssue[];
  fixtures: McpFnClientProfileFixtureResult[];
  error?: string;
}

export interface McpFnClientProfileContractReport {
  formatVersion: 1;
  kind: "mcpfn.client-profile-contract-report";
  status: "complete" | "incomplete";
  ok: boolean;
  profiles: McpFnClientProfileContractResult[];
  droppedProfiles: number;
  incompleteReason?: string;
}

/** A complete bounded report with retry ownership for unfinished target cleanup. */
export class McpFnClientProfileContractCleanupError extends Error {
  constructor(
    readonly report: McpFnClientProfileContractReport,
    private readonly owners: readonly McpFnTestClientCleanupError[],
  ) {
    super("Client profile target cleanup remains pending; retain this error and retryCleanup()");
    this.name = "McpFnClientProfileContractCleanupError";
  }

  async retryCleanup(): Promise<void> {
    const results = await Promise.allSettled(this.owners.map(owner => owner.retryCleanup()));
    if (results.some(result => result.status === "rejected")) throw this;
  }
}

class ProfileCaseCleanupError extends Error {
  constructor(readonly owner: McpFnTestClientCleanupError, readonly result: McpFnClientProfileContractResult) {
    super("Client profile target cleanup remains pending");
  }
}

const PORTABILITY_KEYWORDS = new Set([
  "$anchor",
  "$recursiveAnchor",
  "$recursiveRef",
  "$dynamicAnchor",
  "$dynamicRef",
  "dependentSchemas",
  "dependentRequired",
  "minContains",
  "maxContains",
  "prefixItems",
  "unevaluatedItems",
  "unevaluatedProperties",
]);

function hash(value: unknown): string {
  return createHash("sha256").update(stableJson(value)).digest("hex");
}

function boundedError(value: unknown): string {
  const redacted = String(
    redactOAuthValue(value instanceof Error ? value.message : value),
  );
  return redacted.slice(0, 512);
}

function assertProfileReference(id: string, version: string): void {
  for (const [label, value] of [
    ["id", id],
    ["version", version],
  ] as const) {
    if (typeof value !== "string" || !value || value.length > 128 || !/^[A-Za-z0-9._/-]+$/.test(value)) {
      throw new Error(
        `Client profile ${label} must be a non-empty stable identifier`,
      );
    }
  }
}

export function createMcpFnClientProfileSnapshot(
  profile: { id: string; version: string },
  tools: readonly Tool[],
): McpFnClientProfileSnapshot {
  assertProfileReference(profile.id, profile.version);
  const normalized = [...tools]
    .map((tool) => structuredClone(tool))
    .sort((left, right) =>
      left.name < right.name ? -1 : left.name > right.name ? 1 : 0,
    );
  if (normalized.some((tool, index) => index > 0 && tool.name === normalized[index - 1].name)) {
    throw new Error("Effective catalog contains duplicate tool names");
  }
  return {
    formatVersion: 1,
    kind: "mcpfn.client-profile-snapshot",
    profile: { id: profile.id, version: profile.version },
    catalogHash: hash(normalized),
    tools: normalized.map((tool) => ({ name: tool.name, hash: hash(tool) })),
  };
}

function assertSnapshotFields(value: unknown, fields: readonly string[], location: string): void {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`Client profile snapshot ${location} must be an object`);
  }
  const key = Object.keys(value).find(key => !fields.includes(key));
  if (key !== undefined) {
    throw new Error(`Client profile snapshot contains unsupported fields at ${location}: ${JSON.stringify(key.slice(0, 128))}`);
  }
}

export function validateMcpFnClientProfileSnapshot(
  value: unknown,
): McpFnClientProfileSnapshot {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Client profile snapshot must be an object");
  }
  assertSnapshotFields(value, ["formatVersion", "kind", "profile", "catalogHash", "tools"], "root");
  const snapshot = value as Partial<McpFnClientProfileSnapshot>;
  if (
    snapshot.formatVersion !== 1 ||
    snapshot.kind !== "mcpfn.client-profile-snapshot"
  ) {
    throw new Error("Unsupported client profile snapshot format");
  }
  if (!snapshot.profile)
    throw new Error("Client profile snapshot requires profile metadata");
  assertSnapshotFields(snapshot.profile, ["id", "version"], "profile");
  assertProfileReference(snapshot.profile.id, snapshot.profile.version);
  if (
    typeof snapshot.catalogHash !== "string" ||
    !/^[a-f0-9]{64}$/.test(snapshot.catalogHash)
  ) {
    throw new Error("Client profile snapshot requires a SHA-256 catalogHash");
  }
  if (!Array.isArray(snapshot.tools))
    throw new Error("Client profile snapshot tools must be an array");
  let prior = "";
  for (const [index, tool] of snapshot.tools.entries()) {
    assertSnapshotFields(tool, ["name", "hash"], `tools[${index}]`);
    if (
      !tool ||
      typeof tool.name !== "string" ||
      !tool.name ||
      !/^[a-f0-9]{64}$/.test(tool.hash)
    ) {
      throw new Error("Client profile snapshot contains an invalid tool entry");
    }
    if (tool.name <= prior)
      throw new Error(
        "Client profile snapshot tools must be sorted and unique",
      );
    prior = tool.name;
  }
  return snapshot as McpFnClientProfileSnapshot;
}

export function diffMcpFnClientProfileSnapshots(
  beforeValue: unknown,
  afterValue: unknown,
): McpFnClientProfileSnapshotDiff {
  const before = validateMcpFnClientProfileSnapshot(beforeValue);
  const after = validateMcpFnClientProfileSnapshot(afterValue);
  if (before.profile.id !== after.profile.id) {
    throw new Error("Cannot diff snapshots for different client profile ids");
  }
  const beforeByName = new Map(
    before.tools.map((tool) => [tool.name, tool.hash]),
  );
  const afterByName = new Map(
    after.tools.map((tool) => [tool.name, tool.hash]),
  );
  const names = [
    ...new Set([...beforeByName.keys(), ...afterByName.keys()]),
  ].sort((left, right) => left < right ? -1 : left > right ? 1 : 0);
  const changes: McpFnClientProfileSnapshotChange[] = [];
  for (const tool of names) {
    const beforeHash = beforeByName.get(tool);
    const afterHash = afterByName.get(tool);
    if (!beforeHash) changes.push({ kind: "added", tool, afterHash });
    else if (!afterHash) changes.push({ kind: "removed", tool, beforeHash });
    else if (beforeHash !== afterHash) {
      changes.push({ kind: "modified", tool, beforeHash, afterHash });
    }
  }
  if ((changes.length === 0) !== (before.catalogHash === after.catalogHash)) {
    throw new Error("Inconsistent catalog hashes for tool entries");
  }
  const summary = {
    added: changes.filter(({ kind }) => kind === "added").length,
    removed: changes.filter(({ kind }) => kind === "removed").length,
    modified: changes.filter(({ kind }) => kind === "modified").length,
  };
  return { compatible: summary.removed === 0, changes, summary };
}

function createDialectValidator(dialect: string) {
  const normalized = dialect.replace(/#$/, "");
  if (
    normalized === "http://json-schema.org/draft-07/schema" ||
    normalized === "https://json-schema.org/draft-07/schema"
  )
    return new Ajv({ allErrors: true, strict: false, validateFormats: false });
  if (
    normalized === "http://json-schema.org/draft/2019-09/schema" ||
    normalized === "https://json-schema.org/draft/2019-09/schema"
  )
    return new Ajv2019({
      allErrors: true,
      strict: false,
      validateFormats: false,
    });
  if (
    normalized === "http://json-schema.org/draft/2020-12/schema" ||
    normalized === "https://json-schema.org/draft/2020-12/schema"
  )
    return new Ajv2020({
      allErrors: true,
      strict: false,
      validateFormats: false,
    });
  return undefined;
}

function pointerSegment(value: string): string {
  return value.replaceAll("~", "~0").replaceAll("/", "~1");
}

function walkSchema(
  value: unknown,
  path: string,
  visit: (keyword: string, path: string, schema: Record<string, unknown>) => void,
): void {
  if (!value || typeof value !== "object") return;
  const schema = value as Record<string, unknown>;
  for (const keyword of Object.keys(schema)) {
    visit(keyword, `${path}/${pointerSegment(keyword)}`, schema);
  }
  for (const mapKeyword of [
    "$defs",
    "definitions",
    "dependencies",
    "dependentSchemas",
    "patternProperties",
    "properties",
  ]) {
    const entries = schema[mapKeyword];
    if (!entries || typeof entries !== "object" || Array.isArray(entries))
      continue;
    for (const [name, child] of Object.entries(
      entries as Record<string, unknown>,
    )) {
      walkSchema(child, `${path}/${mapKeyword}/${pointerSegment(name)}`, visit);
    }
  }
  for (const arrayKeyword of ["allOf", "anyOf", "oneOf", "prefixItems", "items"]) {
    const entries = schema[arrayKeyword];
    if (!Array.isArray(entries)) continue;
    entries.forEach((child, index) =>
      walkSchema(child, `${path}/${arrayKeyword}/${index}`, visit),
    );
  }
  for (const schemaKeyword of [
    "additionalItems",
    "additionalProperties",
    "contains",
    "contentSchema",
    "else",
    "if",
    "items",
    "not",
    "propertyNames",
    "then",
    "unevaluatedItems",
    "unevaluatedProperties",
  ]) {
    const child = schema[schemaKeyword];
    if (child && typeof child === "object" && !Array.isArray(child)) {
      walkSchema(child, `${path}/${schemaKeyword}`, visit);
    }
  }
}

export function validateMcpFnSchemaPortability(
  schema: unknown,
  path: string,
  policy: McpFnSchemaPortabilityPolicy = {},
): McpFnSchemaPortabilityIssue[] {
  if (!schema || typeof schema !== "object" || Array.isArray(schema)) {
    return [
      {
        severity: "error",
        code: "schema-invalid",
        path,
        message: "Tool schema must be an object",
      },
    ];
  }
  const declared = (schema as Record<string, unknown>).$schema;
  const dialect =
    typeof declared === "string"
      ? declared
      : "http://json-schema.org/draft-07/schema#";
  const validator = createDialectValidator(dialect);
  if (!validator) {
    return [
      {
        severity: "error",
        code: "schema-dialect-unsupported",
        path: `${path}/$schema`,
        message: boundedError(`Unsupported JSON Schema dialect ${dialect}`),
      },
    ];
  }
  const issues: McpFnSchemaPortabilityIssue[] = [];
  try {
    validator.compile(schema);
  } catch (error) {
    issues.push({
      severity: "error",
      code: "schema-invalid",
      path,
      message: boundedError(error),
    });
  }
  const allowed = new Set(policy.allowKeywords ?? []);
  const modernDialect = /draft\/(2019-09|2020-12)\/schema#?$/.test(dialect);
  const assertionKeywords = new Set([
    "type", "enum", "const", "multipleOf", "maximum", "exclusiveMaximum", "minimum", "exclusiveMinimum",
    "maxLength", "minLength", "pattern", "format", "maxItems", "minItems", "uniqueItems", "contains",
    "minContains", "maxContains", "maxProperties", "minProperties", "required", "dependentRequired",
    "properties", "patternProperties", "additionalProperties", "propertyNames", "dependentSchemas",
    "items", "prefixItems", "additionalItems", "unevaluatedItems", "unevaluatedProperties",
    "allOf", "anyOf", "oneOf", "not", "if", "then", "else",
  ]);
  walkSchema(schema, path, (keyword, keywordPath, node) => {
    if (modernDialect && keyword === "$ref" && !allowed.has(keyword) &&
        Object.keys(node).some(sibling => assertionKeywords.has(sibling))) {
      issues.push({ severity: policy.warningsAsErrors ? "error" : "warning",
        code: "schema-portability-warning", path: keywordPath, keyword,
        message: "$ref assertion siblings are evaluated by modern dialects but ignored by draft-07 clients",
      });
    }
    if (!PORTABILITY_KEYWORDS.has(keyword) || allowed.has(keyword)) return;
    issues.push({
      severity: policy.warningsAsErrors ? "error" : "warning",
      code: "schema-portability-warning",
      path: keywordPath,
      keyword,
      message: `${keyword} is valid but may reduce client portability`,
    });
  });
  return issues.sort((left, right) =>
    left.path < right.path ? -1 : left.path > right.path ? 1 : 0,
  );
}

function extractError(
  result: CallToolResult,
): Record<string, unknown> | undefined {
  const structured = result.structuredContent as
    | Record<string, unknown>
    | undefined;
  if (structured?.error && typeof structured.error === "object") {
    return structured.error as Record<string, unknown>;
  }
  const text = result.content.find((content) => content.type === "text")?.text;
  if (!text) return undefined;
  try {
    const parsed = JSON.parse(text) as { error?: unknown };
    return parsed.error && typeof parsed.error === "object"
      ? (parsed.error as Record<string, unknown>)
      : undefined;
  } catch {
    return undefined;
  }
}

function fixtureFailure(
  result: CallToolResult,
  fixture: McpFnClientProfileFixture,
): string | undefined {
  const expected = fixture.expect;
  if (fixture.source !== "captured-failure" && result.isError) return "Minimal-valid fixture returned isError=true";
  if (fixture.source === "captured-failure" && !result.isError) return "Captured failure did not reproduce an error";
  if (!expected)
    return result.isError ? "Tool returned isError=true" : undefined;
  if (
    expected.isError !== undefined &&
    Boolean(result.isError) !== expected.isError
  ) {
    return `Expected isError=${expected.isError}, received ${Boolean(result.isError)}`;
  }
  if (
    expected.structuredContent !== undefined &&
    stableJson(result.structuredContent) !==
      stableJson(expected.structuredContent)
  )
    return "Structured content did not match the fixture expectation";
  const error = extractError(result);
  if (expected.errorCode !== undefined && error?.code !== expected.errorCode) {
    return "Error code did not match the declared expectation";
  }
  const details =
    error?.details && typeof error.details === "object"
      ? (error.details as Record<string, unknown>)
      : undefined;
  if (
    expected.lifecycleStage !== undefined &&
    details?.lifecycleStage !== expected.lifecycleStage
  )
    return `Expected lifecycle stage ${expected.lifecycleStage}`;
  if (expected.validationIssue) {
    const issues = Array.isArray(details?.issues)
      ? (details.issues as Record<string, unknown>[])
      : [];
    const fields = Object.entries(expected.validationIssue).filter(([, value]) => value !== undefined);
    const matched = fields.length > 0 && issues.some((issue) =>
      fields.every(
        ([key, value]) => issue[key] === value,
      ),
    );
    if (!matched)
      return "Expected structured validation issue was not reported";
  }
  return undefined;
}

async function runProfileCase(
  profileCase: McpFnClientProfileContractCase,
  allowSideEffects: boolean,
): Promise<McpFnClientProfileContractResult> {
  const profile = { id: profileCase.id, version: profileCase.version };
  let client: McpFnTestClient | undefined;
  let configurationError: Error | undefined;
  let pendingFailure: unknown;
  let hasPendingFailure = false;
  let cleanupOwner: McpFnTestClientCleanupError | undefined;
  let result: McpFnClientProfileContractResult = {
    profile,
    status: "complete",
    ok: false,
    portability: [],
    fixtures: [],
  };
  try {
    try {
      client = await McpFnTestClient.connectTarget(
        profileCase.target,
        profileCase.clientInfo ?? {
          name: "mcpfn-profile-suite",
          version: "1.0.0",
        },
        { ...profileCase.client, capabilities: profileCase.capabilities },
      );
    } catch (error) {
      if (error instanceof McpFnTestClientCleanupError) throw error;
      return { ...result, phase: "connect", error: "Target connection failed" };
    }
    let tools: Tool[] | undefined;
    try {
      tools = await client.listTools();
      const repeatedTools = await client.listTools();
      if (stableJson(tools) !== stableJson(repeatedTools)) {
        throw new Error(
          "Effective catalog changed across identical profile list requests",
        );
      }
      result.snapshot = createMcpFnClientProfileSnapshot(profile, tools);
      result.snapshotMatches = profileCase.expectedSnapshot
        ? stableJson(result.snapshot) ===
          stableJson(profileCase.expectedSnapshot)
        : undefined;
      for (const tool of tools) {
        result.portability.push(
          ...validateMcpFnSchemaPortability(
            tool.inputSchema,
            `tools/${tool.name}/inputSchema`,
            profileCase.portability,
          ),
        );
        if (tool.outputSchema) {
          result.portability.push(
            ...validateMcpFnSchemaPortability(
              tool.outputSchema,
              `tools/${tool.name}/outputSchema`,
              profileCase.portability,
            ),
          );
        }
      }
    } catch (error) {
      tools = undefined;
      result = { ...result, phase: "catalog", error: "Target catalog validation failed" };
    }
    if (tools) {
      const advertised = new Set(tools.map(({ name }) => name));
      const taskRequired = new Set(tools.filter(tool => tool.execution?.taskSupport === "required").map(tool => tool.name));
      if (profileCase.fixtures?.some(fixture => taskRequired.has(fixture.tool))) {
        configurationError = new Error(`Client profile ${profile.id}@${profile.version} task-required fixtures are unsupported by this contract runner`);
        throw configurationError;
      }
      for (const fixture of profileCase.fixtures ?? []) {
        const base = {
          name: fixture.name,
          tool: fixture.tool,
          source: fixture.source ?? ("minimal-valid" as const),
        };
        if (!advertised.has(fixture.tool)) {
          result.fixtures.push({
            ...base,
            status: "failed",
            code: "fixture-tool-not-advertised",
            error:
              "Fixture references a tool absent from the effective catalog",
          });
          continue;
        }
        if (fixture.sideEffect !== "read-only" && !allowSideEffects) {
          result.fixtures.push({
            ...base,
            status: "incomplete",
            code: "side-effect-not-authorized",
            error:
              "Fixture was not executed because side effects were not explicitly allowed",
          });
          continue;
        }
        try {
          const callResult = await client.callTool(
            fixture.tool,
            fixture.arguments ?? {},
          );
          const failure = fixtureFailure(callResult, fixture);
          result.fixtures.push(
            failure
              ? {
                  ...base,
                  status: "failed",
                  code: "fixture-expectation-failed",
                  error: failure,
                }
              : { ...base, status: "passed" },
          );
        } catch (error) {
          result.fixtures.push({
            ...base,
            status: "failed",
            code: "fixture-call-failed",
            error: "Tool invocation failed; argument values and exception text are omitted",
          });
        }
      }
      const incomplete = result.fixtures.some(
        ({ status }) => status === "incomplete",
      );
      const failed =
        result.fixtures.some(({ status }) => status === "failed") ||
        result.portability.some(({ severity }) => severity === "error") ||
        result.snapshotMatches === false;
      result = {
        ...result,
        phase: result.snapshotMatches === false || result.portability.some(({ severity }) => severity === "error")
          ? "catalog" : failed || incomplete ? "fixtures" : undefined,
        status: incomplete ? "incomplete" : "complete",
        ok: !failed && !incomplete,
        ...(result.snapshotMatches === false
          ? {
              error:
                "Effective catalog does not match the reviewed profile snapshot",
            }
          : {}),
      };
    }
  } catch (error) {
    pendingFailure = error;
    hasPendingFailure = true;
  } finally {
    if (client) {
      try {
        await client.close();
      } catch (error) {
        if (error instanceof McpFnTestClientCleanupError) cleanupOwner = error;
        else {
