function objectRecord(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : undefined;
}

function redactedFailureCause(error: unknown): Record<string, unknown> | undefined {
  if (!error || typeof error !== "object") return undefined;
  const cause = (error as { cause?: unknown }).cause;
  if (cause === undefined) return undefined;
  return objectRecord(redactOAuthValue(cause, {
    maxDepth: 4,
    maxArrayEntries: 20,
    maxObjectEntries: 20,
    maxStringLength: 1_024,
  }));
}

function resourceDenied(
  layer: McpFnFailureLayer,
  record: Record<string, unknown>,
  cause: Record<string, unknown> | undefined,
): boolean {
  if (layer === "authorization-server") return false;
  return [cause?.code, cause?.status, record.code, record.status]
    .some(value => [401, 403].includes(Number(value)));
}

export function normalizeMcpFnReportFailure(
  error: unknown,
  fallbackPhase?: McpFnDiagnosticPhase | "scenario" | "upstream-conformance",
): McpFnReportFailure {
  const redacted = redactOAuthValue(error, {
    maxDepth: 6,
    maxArrayEntries: 50,
    maxObjectEntries: 50,
    maxStringLength: 2_048,
  });
  const record = objectRecord(redacted) ?? {};
  const phase = stringField(record.phase) ?? fallbackPhase;
  const details = objectRecord(record.details);
  let message = stringField(record.message) ?? String(
    redactOAuthValue(error instanceof Error ? error.message : String(error)),
  );
  const causeRecord = redactedFailureCause(error);
  const causeMessage = stringField(causeRecord?.message);
  if (causeMessage && !message.includes(causeMessage)) message = `${message}: ${causeMessage}`;
  const combinedDetails = causeRecord ? { ...details, cause: causeRecord } : details;
  const layer = failureLayer(phase);
  const deniedByResource = resourceDenied(layer, record, causeRecord);
  return {
    name: stringField(record.name) ?? "Error",
    message,
    layer: deniedByResource ? "resource-server" : layer,
    ...(stringField(record.code) ? { code: stringField(record.code)! } : {}),
    ...(phase ? { phase } : {}),
    ...(combinedDetails ? { details: combinedDetails } : {}),
  };
}

/** Serialize a redacted target-suite report as bounded JUnit XML. */
export function createMcpFnTargetSuiteJUnit(
  report: McpFnTargetSuiteReport,
  options: McpFnJunitOptions = {},
): string {
  const maxBytes = options.maxBytes ?? 1_048_576;
  validateArtifactCap(maxBytes);
  const safe = redactOAuthValue(report, {
    maxDepth: 10,
    maxArrayEntries: 1_000,
    maxObjectEntries: 200,
    maxStringLength: 4_096,
  }) as unknown as McpFnTargetSuiteReport;
  // Redaction appends a string sentinel when an array exceeds its cap.
  const results = safe.results.filter((result) => result && typeof result === "object" && typeof result.name === "string");
  const omitted = report.results.length - results.length;
  const cases = results.map((result) => {
    const duration = Math.max(0, result.durationMs ?? 0) / 1_000;
    let failure = "";
    if (result.status !== "passed") {
      const failureType = result.status === "failed" ? "scenario" : "incomplete";
      failure = junitFailure(result.error ?? `Scenario ${result.status}`, failureType);
    }
    return `    <testcase name="${xml(result.name)}" classname="mcpfn.scenario" time="${duration.toFixed(3)}">${failure}</testcase>`;
  });
  if (safe.failure) {
    cases.unshift(
      `    <testcase name="${xml(safe.failure.phase ?? "target")}" classname="mcpfn.${xml(safe.failure.layer)}" time="0.000">${junitFailure(safe.failure.message, safe.failure.code ?? safe.failure.layer)}</testcase>`,
    );
  }
  if (safe.status === "incomplete" || omitted > 0 || (!safe.ok && !safe.failure && results.every((result) => result.status === "passed"))) {
    cases.push(`    <testcase name="suite-incomplete" classname="mcpfn.report" time="0.000">${junitFailure(safe.incompleteReason ?? "Suite evidence is incomplete or omitted", "incomplete")}</testcase>`);
  }
  if (cases.length === 0) {
    cases.push(
      '    <testcase name="target-suite" classname="mcpfn.target" time="0.000"></testcase>',
    );
  }
  const failures = cases.filter((entry) => entry.includes("<failure ")).length;
  let serialized = junitDocument(safe, cases, failures);
  if (bytes(serialized) <= maxBytes) {
    return preserveMcpFnTargetSuiteArtifact(report, serialized);
  }

  const boundedCases = [
    `    <testcase name="artifact-cap" classname="mcpfn.report" time="0.000">${junitFailure("JUnit content exceeded maxBytes and was truncated", "incomplete")}</testcase>`,
  ];
  serialized = junitDocument(safe, boundedCases, 1, true);
  if (bytes(serialized) > maxBytes) {
    throw new Error("The minimum McpFn JUnit report exceeds maxBytes");
  }
  return preserveMcpFnTargetSuiteArtifact(report, serialized);
}

function junitDocument(
  report: McpFnTargetSuiteReport,
  cases: string[],
  failures: number,
  truncated = false,
): string {
  const suiteName = String(redactOAuthValue(`mcpfn:${report.target.kind}`));
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    `<testsuite name="${xml(suiteName)}" tests="${cases.length}" failures="${failures}" errors="0" skipped="0">`,
    "  <properties>",
    `    <property name="mcpfn.report.schema" value="${xml(MCPFN_REPORT_SCHEMA_VERSION)}"/>`,
    `    <property name="mcpfn.testing.version" value="${xml(MCPFN_TESTING_VERSION)}"/>`,
    `    <property name="node.version" value="${xml(report.runtime.node)}"/>`,
    `    <property name="artifact.truncated" value="${truncated}"/>`,
    "  </properties>",
    ...cases,
    "</testsuite>",
    "",
  ].join("\n");
}

function junitFailure(message: string, type: string): string {
  const safe = String(redactOAuthValue(message, { maxStringLength: 4_096 }));
  return `<failure type="${xml(type)}" message="${xml(safe)}">${xml(safe)}</failure>`;
}

function failureLayer(phase: string | undefined): McpFnFailureLayer {
  if (phase === "resource-discovery" || phase === "transport-connect") {
    return "resource-server";
  }
  if (
    phase === "authorization-server-discovery" ||
    phase === "client-registration" ||
    phase === "authorization-request" ||
    phase === "authorization-callback" ||
    phase === "token-exchange" ||
    phase === "token-refresh" ||
    phase === "token-revocation"
  ) {
    return "authorization-server";
  }
  if (phase === "mcp-initialize" || phase === "capability-operation") {
    return "mcp-initialization";
  }
  if (phase === "scenario") return "scenario";
  if (phase === "upstream-conformance") return "upstream-conformance";
  return "mcpfn-preflight";
}

function stringField(value: unknown): string | undefined {
  if (typeof value === "string") return value;
  if (typeof value === "number") return String(value);
  return undefined;
}

function xml(value: string): string {
  return stripInvalidXmlControls(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

function stripInvalidXmlControls(value: string): string {
  return value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\uFFFE\uFFFF\uD800-\uDFFF]/gu, "");
}

function validateArtifactCap(maxBytes: number): void {
  if (!Number.isInteger(maxBytes) || maxBytes < 1_024) {
    throw new Error("maxBytes must be an integer of at least 1024");
  }
}

function bytes(value: string): number {
  return new TextEncoder().encode(value).byteLength;
}
","import { McpFnClientError } from "@mcpfn/client";

import type { McpFnTargetSuiteReport } from "./suite.js";

interface McpFnTargetSuiteArtifactGuard {
  maxBytes: number;
  validate(value: string): boolean;
  release(): void;
}

const targetSuiteArtifactGuards = new WeakMap<
  McpFnTargetSuiteReport,
  McpFnTargetSuiteArtifactGuard
>();
const targetSuiteArtifactFinalizer = new FinalizationRegistry<() => void>(release => {
  try { release(); } catch {}
});

/** Retain target-aware proof for artifacts derived after suite execution. */
export function registerMcpFnTargetSuiteArtifactGuard(
  report: McpFnTargetSuiteReport,
  validate: (value: string) => boolean,
  release: () => void,
  maxBytes: number,
): void {
  const previous = targetSuiteArtifactGuards.get(report);
  if (previous) {
    targetSuiteArtifactFinalizer.unregister(report);
    targetSuiteArtifactGuards.delete(report);
    previous.release();
  }
  let active = true;
  const releaseOnce = () => {
    if (!active) return;
    active = false;
    release();
  };
  targetSuiteArtifactGuards.set(report, { maxBytes, validate, release: releaseOnce });
  targetSuiteArtifactFinalizer.register(report, releaseOnce, report);
}

export function disposeMcpFnTargetSuiteArtifactGuard(
  report: McpFnTargetSuiteReport,
): void {
  const guard = targetSuiteArtifactGuards.get(report);
  if (!guard) return;
  targetSuiteArtifactGuards.delete(report);
  targetSuiteArtifactFinalizer.unregister(report);
  guard.release();
}

export function preserveMcpFnTargetSuiteArtifact(
  report: McpFnTargetSuiteReport,
  artifact: string,
): string {
  const guard = targetSuiteArtifactGuards.get(report);
  if (!guard) {
    if (report.artifactValidation === "target-aware") {
      throw new McpFnClientError(
        "MCPFN_OPERATION_FAILED",
        "MCP target artifact proof is unavailable",
        { phase: "capability-operation" },
      );
    }
    return artifact;
  }
  if (new TextEncoder().encode(artifact).byteLength > guard.maxBytes) {
    throw new Error("Serialized target suite artifact exceeds maxReportBytes");
  }
  try {
    if (!guard.validate(artifact)) throw new Error("unsafe serialized artifact");
    return artifact;
  } catch {
    throw new McpFnClientError(
      "MCPFN_OPERATION_FAILED",
      "MCP artifact structure conflicts with credential redaction",
      { phase: "capability-operation" },
    );
  }
}
","import {
  MCP_APP_EXTENSION_ID,
  type McpFnManifest,
} from "@mcpfn/core";

export type McpFnServerFeature =
  | "tools"
  | "resources"
  | "prompts"
  | "completions"
  | "tasks"
  | "logging";

export interface McpFnHostProfile {
  id: string;
  name: string;
  protocolVersions: string[];
  serverFeatures: McpFnServerFeature[];
  clientFeatures?: {
    sampling?: boolean;
    elicitation?: Array<"form" | "url">;
    roots?: boolean;
  };
  extensions?: string[];
}

export interface McpFnHostCompatibilityIssue {
  severity: "incompatible" | "degraded";
  code: string;
  path: string;
  message: string;
}

export interface McpFnHostCompatibilityResult {
  status: "compatible" | "degraded" | "incompatible";
  compatible: boolean;
  issues: McpFnHostCompatibilityIssue[];
}

export const MCPFN_HOST_PROFILES = {
  toolsOnly: {
    id: "mcpfn/tools-only",
    name: "Tools-only MCP host",
    protocolVersions: ["2025-03-26", "2025-06-18", "2025-11-25"],
    serverFeatures: ["tools"],
  },
  fullProtocol: {
    id: "mcpfn/full-protocol",
    name: "Full protocol MCP host",
    protocolVersions: ["2025-03-26", "2025-06-18", "2025-11-25"],
    serverFeatures: ["tools", "resources", "prompts", "completions", "tasks", "logging"],
    clientFeatures: { sampling: true, elicitation: ["form", "url"], roots: true },
  },
  mcpApps: {
    id: "mcpfn/mcp-apps",
    name: "Full protocol host with MCP Apps",
    protocolVersions: ["2025-11-25"],
    serverFeatures: ["tools", "resources", "prompts", "completions", "tasks", "logging"],
    clientFeatures: { sampling: true, elicitation: ["form", "url"], roots: true },
    extensions: [MCP_APP_EXTENSION_ID],
  },
} as const satisfies Record<string, McpFnHostProfile>;

export function checkHostCompatibility(
  manifest: McpFnManifest,
  profile: McpFnHostProfile,
): McpFnHostCompatibilityResult {
  const issues: McpFnHostCompatibilityIssue[] = [];
  if (
    manifest.protocolVersions?.length &&
    !manifest.protocolVersions.some((version) => profile.protocolVersions.includes(version))
  ) {
    issues.push({
      severity: "incompatible",
      code: "protocol-version-mismatch",
      path: "protocolVersions",
      message: `${profile.name} and ${manifest.server.name} have no protocol version in common`,
    });
  }

  const supportedServerFeatures = new Set(profile.serverFeatures);
  for (const feature of Object.keys(manifest.capabilities ?? {})) {
    if (
      feature === "experimental" ||
      supportedServerFeatures.has(feature as McpFnServerFeature)
    ) continue;
    issues.push({
      severity: "degraded",
      code: "server-feature-unavailable",
      path: `capabilities.${feature}`,
      message: `${profile.name} will not expose the server's ${feature} feature`,
    });
  }

  const required = manifest.clientRequirements;
  if (required?.sampling && !profile.clientFeatures?.sampling) {
    issues.push({
      severity: "incompatible",
      code: "sampling-required",
      path: "clientRequirements.sampling",
      message: `${manifest.server.name} requires client sampling`,
    });
  }
  if (required?.roots && !profile.clientFeatures?.roots) {
    issues.push({
      severity: "incompatible",
      code: "roots-required",
      path: "clientRequirements.roots",
      message: `${manifest.server.name} requires client roots`,
    });
  }
  for (const mode of required?.elicitation ?? []) {
    if (!profile.clientFeatures?.elicitation?.includes(mode)) {
      issues.push({
        severity: "incompatible",
        code: "elicitation-required",
        path: `clientRequirements.elicitation.${mode}`,
        message: `${manifest.server.name} requires ${mode} elicitation`,
      });
    }
  }

  const extensions = new Set(profile.extensions ?? []);
  for (const [extension, configuration] of Object.entries(manifest.extensions ?? {})) {
    if (extensions.has(extension)) continue;
    const requiredExtension =
      configuration && typeof configuration === "object" &&
      (configuration as Record<string, unknown>).required === true;
    issues.push({
      severity: requiredExtension ? "incompatible" : "degraded",
      code: "extension-unavailable",
      path: `extensions.${extension}`,
      message: `${profile.name} does not support ${extension}`,
    });
  }

  if (!extensions.has(MCP_APP_EXTENSION_ID)) {
    for (const tool of manifest.tools) {
      const ui = tool.metadata?.ui as { visibility?: string[] } | undefined;
      if (ui?.visibility?.length && !ui.visibility.includes("model")) {
        issues.push({
          severity: "incompatible",
          code: "app-only-tool-unavailable",
          path: `tools.${tool.name}.metadata.ui.visibility`,
          message: `${tool.name} is app-only but ${profile.name} does not support MCP Apps`,
        });
      }
    }
  }

  issues.sort((left, right) => {
    if (left.path !== right.path) return left.path < right.path ? -1 : 1;
    if (left.code < right.code) return -1;
    if (left.code > right.code) return 1;
    return 0;
  });
  let status: McpFnHostCompatibilityResult["status"] = "compatible";
  if (issues.some((issue) => issue.severity === "incompatible")) {
    status = "incompatible";
  } else if (issues.length > 0) {
    status = "degraded";
  }
  return { status, compatible: status !== "incompatible", issues };
}
