    const expected = (manifest.resources ?? []).find(
      (candidate) => candidate.uri === resource.uri,
    ) ?? (manifest.resourceTemplates ?? []).find(
      (candidate) => new UriTemplate(candidate.uriTemplate).match(resource.uri),
