interface OfficialConformanceOptions {
    url: string;
    suite?: "active" | "all" | "pending";
    scenario?: string;
    expectedFailures?: string;
    outputDir?: string;
    specVersion?: string;
    verbose?: boolean;
    cwd?: string;
    stdio?: "inherit" | "pipe";
    /** Environment names removed before spawning the upstream runner. */
    sensitiveEnvironmentVariables?: readonly string[];
}
interface OfficialConformanceResult {
    formatVersion: 1;
    kind: "mcpfn.official-conformance-report";
    ok: boolean;
    suiteVersion: string;
    exitCode: number;
    stdout: string;
    stderr: string;
    failure?: McpFnReportFailure;
    /** Credential cleanup failure, separate from the upstream runner diagnosis. */
    cleanupFailure?: McpFnReportFailure;
}
interface AuthenticatedConformanceProxy {
    /** Loopback URL to pass to the official conformance runner. */
    url: string;
    close(): Promise<void>;
}
interface AuthenticatedConformanceProxyOptions {
    /** Fixed loopback MCP URL. Requests cannot select a different origin or path. */
    url: string;
    /** Headers injected into requests using the proxy's own authority. Values are never logged. */
    headers: HeadersInit;
}
interface AuthenticatedOfficialConformanceOptions extends OfficialConformanceOptions {
    /** Preferred typed credential lifecycle. */
    credential?: McpFnRemoteCredential | McpFnRemoteCredentialProvider;
    /** Backward-compatible static header input. Prefer credential. */
    headers?: HeadersInit;
}
/**
 * Start a loopback-only streaming proxy for runners that cannot send auth
 * headers. Authenticated requests use one fixed upstream authority and path.
 * Host-manipulation probes are forwarded without injected credentials.
 */
declare function createAuthenticatedConformanceProxy(options: AuthenticatedConformanceProxyOptions): Promise<AuthenticatedConformanceProxy>;
declare function buildOfficialConformanceArgs(options: OfficialConformanceOptions): string[];
declare function buildOfficialConformanceEnvironment(sensitiveNames?: readonly string[], source?: NodeJS.ProcessEnv): NodeJS.ProcessEnv;
declare function runOfficialConformance(options: OfficialConformanceOptions): Promise<OfficialConformanceResult>;
/** Cleanup failed after retries. Retain this error and call retryCleanup(). */
declare class McpFnConformanceCleanupError extends Error {
    readonly result?: OfficialConformanceResult | undefined;
    constructor(release: () => Promise<void>, result?: OfficialConformanceResult | undefined);
    retryCleanup(): Promise<void>;
}
/**
 * Run the pinned official suite against an authenticated MCP endpoint.
 * Always captures stdio (even when inherit is requested) to redact credentials.
 * outputDir is rejected before acquisition; only the returned redacted result is safe to persist.
 */
declare function runAuthenticatedOfficialConformance(options: AuthenticatedOfficialConformanceOptions): Promise<OfficialConformanceResult>;

type McpFnServerFeature = "tools" | "resources" | "prompts" | "completions" | "tasks" | "logging";
interface McpFnHostProfile {
The fixture starts a local mock server that publishes authorization-server discovery, consent UI, callback capture, client metadata variants, PKCE token exchange, refresh rotation, revocation, and an SDK-compatible access-token verifier. Extend the exported `test` with Skillplane's signed-in page or database fixtures; do not copy the OAuth machinery into the application.

See [Testing and CI](https://github.com/21nCo/super-functions/blob/main/mcpfn/TESTING.md) for the complete layered strategy.

Client-profile lifecycle evidence uses `invalid-arguments-handler` when a registered invalid-argument fallback runs. This stage does not imply that the tool handler ran; normal tool execution uses `handler`. Projected schemas select their declared JSON Schema dialect, defaulting to draft 7 to match canonical registry validation. Named `$anchor` definitions are portability-sensitive for older clients.

Projected catalogs support local JSON Pointer and named-anchor references. Dynamic and recursive reference forms fail closed until dialect-correct dynamic-scope comparison is supported. A recovered invalid-input call emits failed input-validation evidence followed by the invalid-argument fallback stage.

When credentials come from environment variables, pass their names in `sensitiveEnvironmentVariables` to authenticated official conformance. Those names are removed case-insensitively before the upstream runner is spawned. The library cannot infer the source of arbitrary provider-returned headers.

Authenticated official conformance always captures stdout and stderr, including when
`stdio: "inherit"` is requested, so credential values can be removed before output
is returned. `outputDir` is rejected before credentials are acquired because the
upstream runner writes raw artifacts directly. Persist the returned redacted result
if an authenticated run needs an artifact. Credential cleanup may be retried after
failure; successful revoke/dispose steps are not repeated.

Authenticated targets provide credential-aware redaction to client diagnostic/event listeners and inspector snapshots and exports while their credentials are active. Export raw operation results before closing the client; application-facing protocol return values retain their original contents. Recorded inspector events are scrubbed before storage.

When authenticated conformance cleanup exhausts retries, `McpFnConformanceCleanupError.result` retains the original runner stdout, stderr, exit code (or 1 for an otherwise successful run), and failure. A separate `cleanupFailure` records cleanup exhaustion; the overall result is failed. The CLI persists this redacted result before exiting nonzero.


### Retrying failed suite cleanup

export class McpFnConformanceCleanupError extends Error {
  constructor(release: () => Promise<void>, readonly result?: OfficialConformanceResult) {
    super("Authenticated conformance credential cleanup failed; retry cleanup");
    this.name = "McpFnConformanceCleanupError";
    retainedConformanceCleanup.set(this, release);
  }
  async retryCleanup(): Promise<void> {
    const release = retainedConformanceCleanup.get(this);
    if (!release) return;
    try { await release(); }
    catch { throw this; }
    retainedConformanceCleanup.delete(this);
  }
}

/**
 * Run the pinned official suite against an authenticated MCP endpoint.
 * Always captures stdio (even when inherit is requested) to redact credentials.
 * outputDir is rejected before acquisition; only the returned redacted result is safe to persist.
 */
export async function runAuthenticatedOfficialConformance(
  options: AuthenticatedOfficialConformanceOptions,
): Promise<OfficialConformanceResult> {
  if (options.outputDir !== undefined) throw new TypeError("Authenticated conformance does not support outputDir; serialize the redacted result instead");
  const { headers, credential, ...conformance } = options;
  if ((headers === undefined) === (credential === undefined)) {
    throw new TypeError("Provide exactly one of credential or headers for authenticated conformance");
  }
  validateAuthenticatedConformanceUrl(conformance.url);
  const lease = await acquireRemoteCredential(
    credential ?? { headers: headers! },
    {
      url: conformance.url,
      requestId: randomUUID(),
    },
  );
  let proxy: AuthenticatedConformanceProxy | undefined;
  let result: OfficialConformanceResult | undefined;
  let operationFailure: { error: Error } | undefined;
  const safeFailure = (error: unknown): { error: Error } => {
    let message = "Authenticated conformance operation failed";
    try { message = redactRemoteCredential(lease.credential, error instanceof Error ? error.message : String(error)); }
    catch { /* Keep a safe fallback if redaction exceeds its budget. */ }
    return { error: new Error(message) };
  };
  try {
    proxy = await createAuthenticatedConformanceProxy({
      url: conformance.url,
      headers: lease.credential.headers,
    });
    result = redactRemoteCredential(lease.credential, await runConformance({ ...conformance, stdio: "pipe", url: proxy.url }, value => String(redactRemoteCredential(lease.credential, value))), { preserveKeys: true });
  } catch (error) {
    operationFailure = safeFailure(error);
  }
  try { await proxy?.close(); }
  catch (error) { operationFailure ??= safeFailure(error); }
  let released = false;
  for (let attempt = 0; attempt < 3; attempt++) {
    try { await lease.release(); released = true; break; } catch { /* Retry transient revocation failure. */ }
  }
  if (!released) {
    const message = "Authenticated conformance credential cleanup failed; retry cleanup";
    const cleanupFailure = normalizeMcpFnReportFailure(new Error(message), lease.cleanupPhase());
    const failedResult = result ? { ...result, ok: false, exitCode: result.exitCode || 1,
      cleanupFailure,
      ...(result.failure ? {} : { failure: cleanupFailure }),
    } : undefined;
    throw new McpFnConformanceCleanupError(() => lease.release(), failedResult);
  }
  if (operationFailure) throw operationFailure.error;
  if (!result) throw new Error("Conformance produced no result");
  return result;
}

