const localRuntimeTests = spawnSync(
  process.execPath,
  [
    "--test",
    "scripts/lib/local-postgres-port.test.mjs",
    "scripts/lib/local-wrangler-config.test.mjs",
    "scripts/lib/local-worker-vars.test.mjs",
    "scripts/local-init.test.mjs",
    "scripts/development-deployment.test.mjs",
    "scripts/development-topology-deployment.test.mjs",
    "scripts/deploy-topology.test.mjs",
    "scripts/production-deployment.test.mjs",
    "scripts/verify-email-production.test.mjs",
    "scripts/migrate-production-origin.test.mjs",
    "scripts/migrate-topology-databases.test.mjs",
    "scripts/migrate-workspace.test.mjs",
    "scripts/r2-conditional-create.test.mjs",
    "scripts/development-entrypoints.test.mjs",
    "scripts/migrate-development.test.mjs",
    "scripts/configure-local-oauth.test.mjs",
    "scripts/test-local-oauth.test.mjs",
    "scripts/production-smoke.test.mjs",
    "scripts/production-topology-safety.test.mjs",
    "scripts/production-deployment.test.mjs",
    "scripts/rollback.test.mjs",
    "scripts/topology-manifest.test.mjs",
    "scripts/topology-deployment.test.mjs",
    "scripts/datafn-ticket-keys.test.mjs",
  ],
  {
    cwd: repoRoot,
    encoding: "utf8",
    stdio: "inherit",
  },
);
if (localRuntimeTests.status !== 0) {
  process.exit(localRuntimeTests.status ?? 1);
}

if (filters.length === 1 && filters[0] === "app" && positional.includes("skills")) {
  const result = spawnSync(
    "pnpm",
    [
      "--filter",
      "@skillplane/app",
      "exec",
      "vitest",
      "run",
      "tests/unit/skills.test.ts",
    ],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

if (
  filters.length === 1 &&
  filters[0] === "@skillplane/domain" &&
  positional.some((name) =>
    ["amendments", "learning-metadata", "policies"].includes(name),
  )
) {
  const result = spawnSync(
    "pnpm",
    [
      "--filter",
      "@skillplane/domain",
      "exec",
      "vitest",
      "run",
      "src/amendments.test.ts",
      "src/learning-metadata.test.ts",
      "src/amendment-policy.test.ts",
    ],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

if (
  filters.length === 1 &&
  filters[0] === "@skillplane/domain" &&
  positional.includes("contexts")
) {
  const result = spawnSync(
    "pnpm",
    ["--filter", "@skillplane/domain", "exec", "vitest", "run", "src/contexts.test.ts"],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

if (
  filters.length === 1 &&
  filters[0] === "@skillplane/mcp-schema" &&
  positional.some((name) => ["amend", "contexts", "schemas"].includes(name))
) {
  const result = spawnSync(
    "pnpm",
    [
      "--filter",
      "@skillplane/mcp-schema",
      "exec",
      "vitest",
      "run",
      "src/schema.test.ts",
      "src/mutation-schema.test.ts",
    ],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

const result = spawnSync("pnpm", ["exec", "turbo", "run", "test:unit", ...args], {
  cwd: repoRoot,
  encoding: "utf8",
  stdio: "inherit",
});
process.exit(result.status ?? 1);
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { describe, it } from "node:test";

async function readConfig(name, directory = "app") {
  const source = await readFile(resolve(directory, name), "utf8");
  return JSON.parse(source.replace(/,\s*([}\]])/gu, "$1"));
}

describe("local app Wrangler configurations", () => {
  it("keeps runtime bindings identical while isolating OTP authority", async () => {
    const [base, authenticated] = await Promise.all([
      readConfig("wrangler.jsonc"),
      readConfig("wrangler.auth.jsonc"),
    ]);

    for (const key of [
      "name",
      "main",
      "compatibility_date",
      "compatibility_flags",
      "assets",
      "r2_buckets",
      "observability",
    ]) {
      assert.deepEqual(authenticated[key], base[key], `${key} must remain in sync`);
    }

    assert.equal(base.send_email, undefined);
    assert.equal(base.name, "skillplane-app-local");
    assert.equal(base.r2_buckets[0].bucket_name, "skillplane-skill-bundles-local");
    assert.notEqual(base.name, "skillplane-app");
    assert.notEqual(base.r2_buckets[0].bucket_name, "skillplane-skill-bundles");
    assert.equal(base.vars.AUTH_MODE, "disabled");
    assert.equal(authenticated.vars.AUTH_MODE, "otp");
    assert.equal(authenticated.send_email[0].name, "SEND_EMAIL");
    assert.deepEqual(authenticated.send_email[0].allowed_sender_addresses, [
      "no-reply@auth-dev.skillplane.dev",
    ]);
  });

  it("keeps the local MCP deploy identity away from production", async () => {
    const config = await readConfig("wrangler.jsonc", "mcp");

    assert.equal(config.name, "skillplane-mcp-local");
    assert.equal(config.r2_buckets[0].bucket_name, "skillplane-skill-bundles-local");
    assert.notEqual(config.name, "skillplane-mcp");
    assert.notEqual(config.r2_buckets[0].bucket_name, "skillplane-skill-bundles");
    assert.deepEqual(config.compatibility_flags, ["nodejs_compat"]);
  });
});

