        WHERE email = $1
        ORDER BY created_at DESC
        LIMIT 1`,
      [active.email],
    );
    expect(challenge.rows[0]?.code_hash).toBe(
      createHash("sha256").update("123456").digest("hex"),
    );
    expect(JSON.stringify(challenge.rows[0])).not.toContain('"123456"');
